def mark_uncloseable_fractional_sym(account_id, symbol, qty=None):
    if account_id and symbol:
        key = (str(account_id), str(symbol).strip())
        is_new = key not in _uncloseable_fractional_syms
        _uncloseable_fractional_syms.add(key)
        if is_new:
            q_sfx = f" ({qty:g} sh)" if isinstance(qty, (int, float)) else ""
            try:
                log_event(
                    "GUARDRAIL",
                    f"Marked sub-1-share fractional remainder on {symbol}{q_sfx} "
                    f"as uncloseable for this session.",
                )
            except Exception:
                pass


def format_order_qty_str(order_qty):
    """Formats an order quantity as a plain decimal string (never scientific
    notation like '1e+06' for 1,000,000 shares)."""
    q = float(order_qty)
    if abs(q - round(q)) <= 1e-6:
        return str(int(round(q)))
    return f"{q:.4f}".rstrip("0").rstrip(".")


def is_uncloseable_fractional_qty(account_id, symbol, qty):
    """Returns True ONLY when (account_id, symbol) had a sub-1-share fractional
    liquidation rejected by the broker AND the current open quantity is strictly
    between 0 and 1 share (0 < abs(qty) < 1.0). Whole shares (>= 1.0) on that
    same symbol are NEVER excluded."""
    try:
        q = abs(float(qty or 0.0))
    except Exception:
        return False
    if q <= 1e-6 or q >= 1.0:
        return False
    return (str(account_id or ""), str(symbol or "").strip()) in _uncloseable_fractional_syms


def get_eastern_now():
    """Returns the current datetime in US Eastern Time (America/New_York,
    automatically handling EST UTC-5 and EDT UTC-4 via US DST rules) so market
    hours (9:30 AM, 4:00 PM ET) and session dates are 100% synced
    regardless of the user's local computer timezone."""
    utc_now = datetime.now(timezone.utc)
    y = utc_now.year
    # US DST starts 2nd Sunday in March at 02:00 EST (07:00 UTC)
    mar1_w = datetime(y, 3, 1).weekday()
    dst_start_day = 8 + (6 - mar1_w) % 7
    dst_start_utc = datetime(y, 3, dst_start_day, 7, 0, 0, tzinfo=timezone.utc)
    # US DST ends 1st Sunday in November at 02:00 EDT (06:00 UTC)
    nov1_w = datetime(y, 11, 1).weekday()
    dst_end_day = 1 + (6 - nov1_w) % 7
    dst_end_utc = datetime(y, 11, dst_end_day, 6, 0, 0, tzinfo=timezone.utc)
    offset_hours = -4 if (dst_start_utc <= utc_now < dst_end_utc) else -5
    return (utc_now + timedelta(hours=offset_hours)).replace(tzinfo=None)


def get_today_str():
    return get_eastern_now().strftime("%Y-%m-%d")


def get_session_key(broker_name, account_id):
    if not broker_name or not account_id:
        return ""
    return f"{broker_name}_{account_id}"


_adapter_epoch = 0
_adapter_epoch_lock = threading.Lock()


def _bump_adapter_epoch():
    """Atomically increments _adapter_epoch whenever the active broker, account,
    or Demo Sandbox state is swapped/reset so any in-flight data_loop() poll
    from the previous epoch aborts cleanly without mutating the new session."""
    global _adapter_epoch
    with _adapter_epoch_lock:
        _adapter_epoch += 1
        return _adapter_epoch


def get_adapter_epoch():
    return _adapter_epoch


def is_demo_mode_active(adapter=None):
    """Returns True ONLY when the interactive Demo Simulator adapter is active.
    Fails closed when a real broker adapter (SchwabAdapter / WebullAdapter) is
    bound so a stale config['active_broker'] == 'DEMO' can never disable live
    lockouts, close guards, or swing-position filters."""
    if adapter is not None:
        return getattr(adapter, "name", "") == "DEMO"
    if active_adapter is not None:
        return getattr(active_adapter, "name", "") == "DEMO"
    return str(config.get("active_broker", "")).upper() == "DEMO"


def is_real_broker_committed_for_today(cfg=None):
    """Returns True ONLY when a real brokerage session (SCHWAB or WEBULL) has
    committed its rulebook for today's Eastern calendar date."""
    c = cfg if isinstance(cfg, dict) else config
    today_str = get_today_str()
    c_broker = str(c.get("committed_broker", "") or "").upper()
    if str(c.get("committed_session_date", "")) == today_str and c_broker in (
        "SCHWAB",
        "WEBULL",
        "",
    ):
        if c_broker in ("SCHWAB", "WEBULL"):
            return True
        if str(c.get("active_broker", "SCHWAB")).upper() in ("SCHWAB", "WEBULL"):
            return True
    acct_sessions = c.get("account_sessions", {})
    if isinstance(acct_sessions, dict):
        for k, s_data in acct_sessions.items():
            if str(k).startswith("DEMO_"):
                continue
            if (
                isinstance(s_data, dict)
                and bool(s_data.get("committed_for_today", False))
                and s_data.get("committed_date") == today_str
            ):
                return True
    return False


def is_committed_for_today(cfg=None, broker_name=None, account_id=None):
    """Returns True when the trader has activated 'Commit Rulebook for Today'
    for the current Eastern calendar day on the target broker/session."""
    c = cfg if isinstance(cfg, dict) else config
    today_str = get_today_str()
    b_name = str(
        broker_name
        or (active_adapter.name if active_adapter is not None else None)
        or c.get("active_broker", "SCHWAB")
    ).upper()
    if (
        broker_name is None
        and committed_for_today
        and (active_session_date is None or active_session_date == today_str)
    ):
        return True
    if b_name != "DEMO":
        c_broker = str(c.get("committed_broker", "") or "").upper()
        if str(c.get("committed_session_date", "")) == today_str and c_broker in (
            "SCHWAB",
            "WEBULL",
            "",
        ):
            return True
    acct_id = (
        account_id
        or (
            active_adapter.account_id
            if active_adapter is not None
            and getattr(active_adapter, "name", "").upper() == b_name
            and active_adapter.account_id
            else None
        )
        or (
            "DEMO-SIM-001"
            if b_name == "DEMO"
            else c.get("brokers", {}).get(b_name, {}).get("selected_account_id", "")
        )
    )
    s_key = get_session_key(b_name, acct_id)
    acct_sessions = (
        _demo_memory_session
        if b_name == "DEMO"
        else c.get("account_sessions", {})
    )
    if s_key and isinstance(acct_sessions, dict) and s_key in acct_sessions:
        s_data = acct_sessions[s_key]
        if (
            isinstance(s_data, dict)
            and bool(s_data.get("committed_for_today", False))
            and s_data.get("committed_date") == today_str
        ):
            return True
    return False


def _classify_preview_order_result(
    http_status=None, body_text="", error_code=""
):
    """Classifies a broker preview_order probe response into strictly one of 3
    states:
      - ("VERIFIED", detail_str): Order preview succeeded (without permission
        rejects) or reached the broker's order-validation engine on a real HTTP
        400/422 or SDK error_code response (proving trading scope/permission).
      - ("BLOCKED", detail_str): Explicit 401/403 or read-only / permission
        denied / unauthorized trading scope rejection.
      - ("UNCONFIRMED", detail_str): Any ambiguous, 404/500/501/503, timeout,
        local Python exception, or unrecognized response (never false green).
    """
    status_int = None
    try:
        if http_status is not None and str(http_status).strip() != "":
            status_int = int(str(http_status).strip())
    except Exception:
        status_int = None

    raw_body = str(body_text or "").strip()
    raw_code = str(error_code or "").strip()
    combined = f"{raw_code} {raw_body}".lower()
    if status_int is None:
        m_http = re.search(r"\bhttp(?:/\d(?:\.\d)?)?[\s:=-]+([1-5]\d{2})\b", combined)
        if m_http:
            try:
                status_int = int(m_http.group(1))
            except Exception:
                status_int = None

    clean_body = re.sub(
        r"(/accounts/)([A-Za-z0-9_-]{4,})",
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}",
        raw_body,
    )
    clean_body = re.sub(
        r'(["\'](?:accountNumber|account_number|account_id|sec_account_id|accountId)["\']\s*:\s*["\']?)([A-Za-z0-9_-]{4,})',
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}",
        clean_body,
    )
    clean_body = re.sub(
        r'(["\'](?:buyingPower|buying_power|cashBalance|cash_balance|liquidationValue|liquidation_value|accountValue|account_value|netLiquidation|net_liquidation|equity|availableFunds|available_funds)["\']\s*:\s*["\']?)[-+]?[0-9]+(?:\.[0-9]+)?(["\']?)',
        r"\1[REDACTED]\2",
        clean_body,
    )
    snip = (clean_body or raw_code or f"HTTP {status_int}")[:120]

    blocked_keywords = (
        "read-only",
        "read_only",
        "readonly",
        "not authorized to trade",
        "not authorized for trade",
        "no_trade_permission",
        "no trade permission",
        "trading_not_allowed",
        "trading not allowed",
        "insufficient_scope",
        "insufficient scope",
        "forbidden",
        "app_not_approved",
        "not approved for trading",
        "permission_denied",
        "permission denied",
        "unauthorized_client",
        "unauthorized",
        "unauthenticated",
        "invalid_token",
        "token_invalid",
        "access_denied",
        "account_restricted_from_trading",
        "trade permission",
        "no permission to trade",
    )

    if status_int in (200, 201) or str(http_status).upper() == "OK":
        if raw_body.startswith("{"):
            try:
                parsed_200 = json.loads(raw_body)
                if isinstance(parsed_200, dict):
                    ov_res = parsed_200.get("orderValidationResult") or {}
                    rejects = (
                        ov_res.get("rejects")
                        if isinstance(ov_res, dict)
                        else None
                    ) or parsed_200.get("rejects") or []
                    err_field = parsed_200.get("error") or parsed_200.get("errors") or ""
                    rej_blob = f"{json.dumps(rejects)} {json.dumps(err_field)}".lower()
                    if any(k in rej_blob for k in blocked_keywords):
                        return (
                            "BLOCKED",
                            f"Broker rejected order preview due to trading permission/scope restriction ({snip}).",
                        )
            except Exception:
                pass
        return (
            "VERIFIED",
            "Order preview endpoint accepted 1-share SPY @ $1.00 probe (HTTP 200).",
        )

    if any(k in combined for k in blocked_keywords):
        return (
            "BLOCKED",
            f"Broker rejected order preview due to trading permission/scope restriction ({snip}).",
        )
    if status_int in (401, 403):
        return (
            "BLOCKED",
            f"Broker returned HTTP {status_int} on order preview ({snip}).",
        )

    order_engine_keywords = (
        "buying power",
        "buying_power",
        "insufficient_funds",
        "insufficient funds",
        "cash balance",
        "margin buying power",
        "margin requirement",
        "margin_requirement",
        "insufficient margin",
        "margin deficit",
        "margin call",
        "day_trade_buying_power",
        "day trade buying power",
        "limit range",
        "price is too far",
        "price out of",
        "price_out_of",
        "out of range",
        "market hours",
        "order_validation",
        "order validation",
        "settled funds",
        "minimum order",
        "insufficient_buying_power",
        "insufficient buying power",
    )
    is_html_err = "<html" in combined or "<!doctype" in combined
    has_broker_err_status = status_int in (400, 422) or (
        status_int is None
        and bool(raw_code)
        and raw_code.upper() not in ("TIMEOUT", "NETWORK_ERROR", "CONNECTION_ERROR")
    )
    if (
        not is_html_err
        and has_broker_err_status
        and any(k in combined for k in order_engine_keywords)
    ):
        return (
            "VERIFIED",
            f"Order reached broker validation engine ({snip}).",
        )

    return (
        "UNCONFIRMED",
        f"Order preview returned inconclusive status ({snip}).",
    )


def format_dollar(val):
    rounded = round(val, 2)
    if rounded > 0:
        return f"+${rounded:,.2f}"
    elif rounded < 0:
        return f"-${abs(rounded):,.2f}"
    return "$0.00"


def get_active_hud_columns(cfg=None):
    raw_cols = (cfg or config).get("hud_columns") or DEFAULT_HUD_COLUMNS
    valid = [c for c in raw_cols if c in HUD_COL_HEADERS]
    return valid if valid else list(DEFAULT_HUD_COLUMNS)


def is_compact_hud(cfg=None):
    """Returns True when the HUD is configured with 3 or fewer columns
    (Small HUD mode), enabling compact status pill text."""
    return len(get_active_hud_columns(cfg)) <= 3


def compute_hud_width(n_cols):
    """Computes HUD pixel width: preserves the classic 480px (3-col) and
    800px (5-col) layouts while tapering column width for 6–8 columns so the
    bar does not over-stretch across the screen."""
    n = max(1, int(n_cols))
    if n <= 3:
        return 480
    if n == 4:
        return 640
    if n == 5:
        return 800
    if n == 6:
        return 840
    if n == 7:
        return 900
    return n * 120


def format_hud_cols_btn_label(cols):
    return f"📊 HUD Columns ({len(cols)})"


def format_trades_wl_multiline(wins, losses):
    total = int(wins) + int(losses)
    if total <= 0:
        return "W: 0 (0.0%)\nL: 0 (0.0%)"
    w_pct = (wins / total) * 100.0
    l_pct = (losses / total) * 100.0
    return f"W: {wins} ({w_pct:.1f}%)\nL: {losses} ({l_pct:.1f}%)"


def format_trades_wl_inline(wins, losses):
    total = int(wins) + int(losses)
    if total <= 0:
        return "W: 0 (0.0%) | L: 0 (0.0%)"
    w_pct = (wins / total) * 100.0
    l_pct = (losses / total) * 100.0
    return f"W: {wins} ({w_pct:.1f}%) | L: {losses} ({l_pct:.1f}%)"


def _format_countdown_mm_ss(seconds):
    """Formats a positive second count as MM:SS (or H:MM:SS if >= 60 mins)."""
    s = max(0, int(seconds))
    m, sec = divmod(s, 60)
    if m >= 60:
        h, rem_m = divmod(m, 60)
        return f"{h:d}:{rem_m:02d}:{sec:02d}"
    return f"{m:02d}:{sec:02d}"


def get_loss_streak_status(now_ts=None):
    """Prunes expired timestamps from recent_loss_timestamps against the active
    rolling window and returns:
      (cur_streak, req_losses, next_drop_sec, full_clear_sec, is_enabled)
    where next_drop_sec is seconds until the oldest loss ages out (-1 to streak)
    and full_clear_sec is seconds until the newest loss ages out (0/X clear)."""
    global recent_loss_timestamps
    if now_ts is None:
        now_ts = time.time()
    req_losses = max(2, int(round(float(config.get("consec_loss_count", 3)))))
    win_mins = max(0.5, float(config.get("consec_loss_window_mins", 15.0)))
    win_sec = win_mins * 60.0
    is_enabled = (
        not config.get("alarms_only_mode", False)
        and bool(config.get("enable_consec_loss_cooldown", False))
    )
    if recent_loss_timestamps:
        recent_loss_timestamps[:] = [
            float(ts)
            for ts in recent_loss_timestamps
            if 0.0 <= (now_ts - float(ts)) < win_sec
        ]
    cur_streak = len(recent_loss_timestamps)
    if cur_streak > 0:
        oldest_rem = (recent_loss_timestamps[0] + win_sec) - now_ts
        newest_rem = (recent_loss_timestamps[-1] + win_sec) - now_ts
        next_drop_sec = max(1, int(math.ceil(oldest_rem)))
        full_clear_sec = max(1, int(math.ceil(newest_rem)))
    else:
        next_drop_sec = 0
        full_clear_sec = 0
    return cur_streak, req_losses, next_drop_sec, full_clear_sec, is_enabled


def format_loss_streak_multiline(now_ts=None):
    """Returns (two_line_text, bg_hex) for the HUD 'LOSS STREAK' column."""
    cur_s, req_l, next_s, _full_s, is_en = get_loss_streak_status(now_ts)
    if cur_s <= 0:
        top_ln = f"0 / {req_l}" if is_en else f"0 / {req_l} (OFF)"
        return f"{top_ln}\nCLEAR", "#2c3e50"
    timer_str = _format_countdown_mm_ss(next_s)
    if not is_en:
        bg_c = "#2c3e50"
    elif cur_s >= (req_l - 1):
        bg_c = "#b03a2e"
    else:
        bg_c = "#d35400"
    return f"{cur_s} / {req_l}\nRST {timer_str}", bg_c


def format_loss_streak_inline(now_ts=None):
    """Returns a single-line streak summary for the HUD bottom-left badge."""
    cur_s, req_l, next_s, _full_s, is_en = get_loss_streak_status(now_ts)
    if cur_s > 0:
        return f"STREAK: {cur_s}/{req_l} ({_format_countdown_mm_ss(next_s)})"
    if is_en:
        return f"STREAK: 0/{req_l} (CLEAR)"
    return f"STREAK: 0/{req_l} (OFF)"


def format_dist_to_stop_hud(distance_to_terminate, locked_down=None):
    """Formats the HUD '$ TO STOP' ('dist_to_term') column value.
    When the Daily Stop is breached/disarmed (is_locked_down) or distance <= 0,
    displays a clear two-line 'BREACHED\\n-$X.XX OVER' readout instead of a
    raw negative dollar string like '$-449.91'."""
    is_ld = is_locked_down if locked_down is None else bool(locked_down)
    dist_val = round(float(distance_to_terminate), 2)
    if is_ld or dist_val <= 0.0:
        if dist_val <= 0.0:
            return f"BREACHED\n-${abs(dist_val):,.2f} OVER"
        return f"BREACHED\n+${dist_val:,.2f} BUF"
    return f"${dist_val:,.2f}"


def _get_effective_rth_tier_stops(t1_max, t2_on, t2_max, t3_on, t3_max):
    """Ensures RTH Profit Ratchet Tiers 2 & 3 never loosen the Daily Stop
    below Starting Max Loss (-t1_max) or a lower enabled tier's stop."""
    base_t1_stop = -abs(float(t1_max))
    eff_t2 = max(base_t1_stop, float(t2_max)) if t2_on else base_t1_stop
    eff_t3 = max(eff_t2, float(t3_max)) if t3_on else eff_t2
    return base_t1_stop, eff_t2, eff_t3


def describe_active_floor(cfg=None, rth_mode=None):
    """Returns (floor_equity, stop_pnl, hud_hdr_tag, tier_short_label,
    tier_full_desc, setting_field_hint) for the currently active Daily Stop
    tier so the HUD, Post-Breach Review dialog, and audit logs always state
    explicitly WHICH rulebook & tier controls the active floor."""
    c = cfg or config
    rth_now = is_rth() if rth_mode is None else bool(rth_mode)
    if start_equity is None or start_equity <= 0.0:
        if not rth_now:
            pm_max = float(c.get("pm_max_loss", 1500.0))
            return (
                None,
                -pm_max,
                "EXT",
                "Ext-Hours Base Stop",
                f"Ext-Hours Starting Max Loss (-${pm_max:,.0f})",
                "Card 4 'Starting Max Loss ($)'",
            )
        t1_max = float(c.get("t1_max_loss", 2000.0))
        return (
            None,
            -t1_max,
            "T1",
            "RTH Tier 1 Base",
            f"RTH Tier 1 Starting Max Loss (-${t1_max:,.0f})",
            "Card 5 'Starting Max Loss ($)'",
        )

    hwm_eq = max_equity if max_equity is not None else start_equity
    max_realized_profit = round(hwm_eq - start_equity, 2)
    if not rth_now:
        pm_lock_on = bool(c.get("enable_pm_lock", True))
        pm_trig = float(c.get("pm_lock_trigger", 500.0))
        pm_trail = float(c.get("pm_trail_cushion", 500.0))
        pm_max = float(c.get("pm_max_loss", 1500.0))
        if pm_lock_on and max_realized_profit >= pm_trig:
            fl_eq = max(start_equity - pm_max, hwm_eq - pm_trail)
            st_pnl = round(fl_eq - start_equity, 2)
            return (
                fl_eq,
                st_pnl,
                "EXT LOCK",
                "Ext-Hours Profit Lock",
                f"Ext-Hours Profit Lock (Unlocked at High {format_dollar(max_realized_profit)} >= +${pm_trig:,.0f}, Trail ${pm_trail:,.0f})",
                "Card 4 'Trail Peak By ($)' (or uncheck 'Profit Lock Trigger')",
            )
        fl_eq = start_equity - pm_max
        return (
            fl_eq,
            round(fl_eq - start_equity, 2),
            "EXT",
            "Ext-Hours Base Stop",
            f"Ext-Hours Starting Max Loss (-${pm_max:,.0f})",
            "Card 4 'Starting Max Loss ($)'",
        )

    t4_on = bool(c.get("enable_t4", True))
    t3_on = bool(c.get("enable_t3", True))
    t2_on = bool(c.get("enable_t2", True))
    t4_trig = float(c.get("t4_trigger", 1000.0))
    t4_trail = float(c.get("t4_trail", 500.0))
    t3_trig = float(c.get("t3_trigger", 500.0))
    t3_max = float(c.get("t3_max_loss", -500.0))
    t2_trig = float(c.get("t2_trigger", 250.0))
    t2_max = float(c.get("t2_max_loss", -1000.0))
    t1_max = float(c.get("t1_max_loss", 2000.0))
    base_t1_stop, eff_t2_max, eff_t3_max = _get_effective_rth_tier_stops(
        t1_max, t2_on, t2_max, t3_on, t3_max
    )
    if t4_on and max_realized_profit >= t4_trig:
        prior_stop_pnl = (
            eff_t3_max
            if (t3_on and max_realized_profit >= t3_trig)
            else (
                eff_t2_max
                if (t2_on and max_realized_profit >= t2_trig)
                else base_t1_stop
            )
        )
        fl_eq = max(start_equity + prior_stop_pnl, hwm_eq - t4_trail)
        st_pnl = round(fl_eq - start_equity, 2)
        return (
            fl_eq,
            st_pnl,
            "T4",
            "RTH Tier 4 Trail",
            f"RTH Tier 4 Trailing Lock (Unlocked at RTH High {format_dollar(max_realized_profit)} >= +${t4_trig:,.0f}, Trail ${t4_trail:,.0f})",
            "Card 5 'Tier 4 — Trail Peak By ($)' (or uncheck Tier 4)",
        )
    if t3_on and max_realized_profit >= t3_trig:
        fl_eq = start_equity + eff_t3_max
        st_pnl = round(fl_eq - start_equity, 2)
        return (
            fl_eq,
            st_pnl,
            "T3",
            "RTH Tier 3 Ratchet",
            f"RTH Tier 3 Stop Ratchet (Unlocked at RTH High {format_dollar(max_realized_profit)} >= +${t3_trig:,.0f})",
            "Card 5 'Tier 3 — Stop Level ($)' (or uncheck Tier 3)",
        )
    if t2_on and max_realized_profit >= t2_trig:
        fl_eq = start_equity + eff_t2_max
        st_pnl = round(fl_eq - start_equity, 2)
        return (
            fl_eq,
            st_pnl,
            "T2",
            "RTH Tier 2 Ratchet",
            f"RTH Tier 2 Stop Ratchet (Unlocked at RTH High {format_dollar(max_realized_profit)} >= +${t2_trig:,.0f})",
            "Card 5 'Tier 2 — Stop Level ($)' (or uncheck Tier 2)",
        )
    fl_eq = start_equity - t1_max
    return (
        fl_eq,
        round(fl_eq - start_equity, 2),
        "T1",
        "RTH Tier 1 Base",
        f"RTH Tier 1 Starting Max Loss (-${t1_max:,.0f})",
        "Card 5 'Starting Max Loss ($)'",
    )


def compute_active_floor_equity(cfg=None, rth_mode=None):
    """Computes the active Daily Stop floor equity for the given config and
    session state (or returns None if start_equity is not yet initialized)."""
    return describe_active_floor(cfg, rth_mode)[0]


def backfill_trades_from_today_log(target_broker=None):
    """If today's log has completed round-trip trades and win/loss counters
    are at 0 (e.g. upgrading mid-day), reconstructs W/L from today's log
    for the specified broker without cross-contaminating other brokers."""
    if not os.path.exists(LOG_PATH):
        return 0, 0, 0.0
    today_str = get_today_str()
    w_cnt = 0
    l_cnt = 0
    prev_real = 0.0
    curr_log_broker = target_broker or "SCHWAB"
    try:
        with open(LOG_PATH, "r", encoding="utf-8") as f:
            first = f.readline()
            if today_str not in first:
                return 0, 0, 0.0
            for line in f:
                if "SCHWAB API authenticated" in line or "Broker=SCHWAB" in line:
                    curr_log_broker = "SCHWAB"
                elif "WEBULL API authenticated" in line or "Broker=WEBULL" in line:
                    curr_log_broker = "WEBULL"

                if "Baseline anchored to:" in line:
                    if target_broker is None or f"({target_broker})" in line:
                        w_cnt = 0
                        l_cnt = 0
                        prev_real = 0.0
                elif (
                    (target_broker is None or curr_log_broker == target_broker)
                    and "[POS_CHANGE]" in line
                    and ("(CLOSED FLAT)" in line or "Re-entry Avg:" in line)
                ):
                    m = re.search(
                        r"Realized:\s*([+-]?)\$(\d[\d,]*\.\d{2})", line
                    )
                    if m:
                        sign = -1.0 if m.group(1) == "-" else 1.0
                        val = sign * float(m.group(2).replace(",", ""))
                        delta = round(val - prev_real, 2)
                        if delta > 0.0:
                            w_cnt += 1
                        elif delta < 0.0:
                            l_cnt += 1
                        prev_real = val
    except Exception:
        pass
    return w_cnt, l_cnt, prev_real


def backfill_min_pnl_from_today_log(target_broker=None, target_start_eq=None):
    """If upgrading mid-day when daily_min_equity was not yet persisted in
    account_sessions, scans today's local log for flat realized PnL troughs on
    the matching broker + starting baseline segment (never cross-contaminating
    accounts or parsing rejected anti-wick lines)."""
    if not os.path.exists(LOG_PATH):
        return 0.0
    today_str = get_today_str()
    min_pnl = 0.0
    curr_log_broker = target_broker or "SCHWAB"
    seg_matches = target_start_eq is None
    tgt_eq = (
        round(float(target_start_eq), 2)
        if target_start_eq is not None
        else None
    )
    try:
        with open(LOG_PATH, "r", encoding="utf-8") as f:
            first = f.readline()
            if today_str not in first:
                return 0.0
            for line in f:
                if "SCHWAB API authenticated" in line or "Broker=SCHWAB" in line:
                    curr_log_broker = "SCHWAB"
                elif "WEBULL API authenticated" in line or "Broker=WEBULL" in line:
                    curr_log_broker = "WEBULL"

                if "Baseline anchored to:" in line:
                    b_ok = target_broker is None or f"({target_broker})" in line
                    if tgt_eq is not None:
                        m_b = re.search(
                            r"Baseline anchored to:\s*\$([0-9,]+(?:\.[0-9]{2})?)",
                            line,
                        )
                        if m_b and b_ok:
                            val_b = round(float(m_b.group(1).replace(",", "")), 2)
                            seg_matches = abs(val_b - tgt_eq) <= 0.02
                            if seg_matches:
                                min_pnl = 0.0
                        else:
                            seg_matches = False
                    elif b_ok:
                        seg_matches = True
                        min_pnl = 0.0
                elif "baseline from memory:" in line and "Start=$" in line:
                    b_ok = (
                        target_broker is None
                        or f"Restored {target_broker} baseline" in line
                    )
                    if tgt_eq is not None:
                        m_s = re.search(
                            r"Start=\$([0-9,]+(?:\.[0-9]{2})?)", line
                        )
                        seg_matches = bool(
                            b_ok
                            and m_s
                            and abs(
                                round(float(m_s.group(1).replace(",", "")), 2)
                                - tgt_eq
                            )
                            <= 0.02
                        )
                elif (
                    "Auto-aligned " in line
                    and " starting baseline from $" in line
                ):
                    b_ok = (
                        target_broker is None
                        or f"Auto-aligned {target_broker} " in line
                    )
                    if tgt_eq is not None:
                        m_a = re.search(
                            r"\s+to\s+\$([0-9,]+(?:\.[0-9]{2})?)", line
                        )
                        seg_matches = bool(
                            b_ok
                            and m_a
                            and abs(
                                round(float(m_a.group(1).replace(",", "")), 2)
                                - tgt_eq
                            )
                            <= 0.02
                        )
                        if seg_matches:
                            min_pnl = 0.0
                elif (
                    seg_matches
                    and (target_broker is None or curr_log_broker == target_broker)
                    and "[POS_CHANGE]" in line
                    and "(CLOSED FLAT)" in line
                    and "Open: $0.00" in line
                ):
                    m = re.search(
                        r"Realized:\s*([+-]?)\$(\d[\d,]*\.\d{2})", line
                    )
                    if m:
                        sign = -1.0 if m.group(1) == "-" else 1.0
                        val = round(
                            sign * float(m.group(2).replace(",", "")), 2
                        )
                        if val < min_pnl:
                            min_pnl = val
    except Exception:
        pass
    return round(min_pnl, 2)


# --- ACTION-ONLY DAILY EVENT LOGGER ---
def _archive_previous_log_and_prune(today_str):
    """Archives an older enforcer_log.txt into ~/enforcer_logs/enforcer_log_YYYY-MM-DD.txt
    and prunes archived log files older than LOG_RETENTION_DAYS (90 days)."""
    archived_path = None
    pruned_count = 0

    try:
        os.makedirs(LOG_ARCHIVE_DIR, exist_ok=True)
    except Exception:
        return None, 0

    if os.path.exists(LOG_PATH):
        try:
            with open(LOG_PATH, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()
            if content.strip():
                first_line = content.splitlines()[0] if content else ""
                m = re.search(r"DATE:\s*(\d{4}-\d{2}-\d{2})", first_line)
                if m:
                    old_date = m.group(1)
                else:
                    mtime = os.path.getmtime(LOG_PATH)
                    old_date = datetime.fromtimestamp(mtime).strftime("%Y-%m-%d")

                if old_date != today_str:
                    dest_path = os.path.join(
                        LOG_ARCHIVE_DIR, f"enforcer_log_{old_date}.txt"
                    )
                    if os.path.exists(dest_path):
                        with open(dest_path, "a", encoding="utf-8") as af:
                            af.write("\n" + content)
                    else:
                        with open(dest_path, "w", encoding="utf-8") as af:
                            af.write(content)
                    archived_path = dest_path
        except Exception as e:
            print(f"Could not archive previous log file: {e}")

    try:
        cutoff_dt = datetime.now() - timedelta(days=LOG_RETENTION_DAYS)
        cutoff_date_str = cutoff_dt.strftime("%Y-%m-%d")
        for fname in os.listdir(LOG_ARCHIVE_DIR):
            m = re.match(r"^enforcer_log_(\d{4}-\d{2}-\d{2})\.txt$", fname)
            if m and m.group(1) < cutoff_date_str:
                try:
                    os.remove(os.path.join(LOG_ARCHIVE_DIR, fname))
                    pruned_count += 1
                except Exception:
                    pass
    except Exception:
        pass

    return archived_path, pruned_count


def _mask_last4(val):
    """Masks an order ID or account identifier to its last 4 characters."""
    s = str(val or "").strip()
    if len(s) > 4:
        return f"...{s[-4:]}"
    return s


def _mask_user_path(text):
    """Replaces the user's home directory path with '~' so Windows usernames
    are never exposed in log files (including JSON-escaped double/quadruple
    backslash paths emitted by third-party SDKs)."""
    out = str(text or "")
    if USER_HOME:
        norm_home = USER_HOME.replace("/", "\\")
        for variant in (
            norm_home.replace("\\", "\\\\\\\\"),
            norm_home.replace("\\", "\\\\"),
            USER_HOME,
            USER_HOME.replace("\\", "/"),
            norm_home,
        ):
            if variant:
                out = re.sub(
                    re.escape(variant), "~", out, flags=re.IGNORECASE
                )
    out = re.sub(r"[A-Za-z]:(?:\\+Users\\+|/Users/)[^\\/\s'\"]+", "~", out)
    return out


def _scrub_log_line(message):
    """Sanitizes a single log message before writing to disk:
    - Masks USER_HOME paths as '~' (including JSON-escaped backslashes)
    - Masks any configured account_id (>4 chars) to '...last4'
    - Masks URL /accounts/<hash> segments, Bearer/OAuth tokens, and SDK JSON headers
    - Masks any long numeric/alphanumeric order IDs in cancel/order lines"""
    msg = _mask_user_path(message)

    try:
        brokers_cfg = config.get("brokers", {})
        for b_info in brokers_cfg.values():
            if isinstance(b_info, dict):
                aid = str(b_info.get("selected_account_id") or "").strip()
                if len(aid) > 4:
                    msg = msg.replace(aid, _mask_last4(aid))
                for c_acct in (b_info.get("cached_accounts") or []):
                    if isinstance(c_acct, dict):
                        cid = str(c_acct.get("id") or "").strip()
                        if len(cid) > 4:
                            msg = msg.replace(cid, _mask_last4(cid))
                for secret_k in ("app_key", "app_secret"):
                    sec_v = str(b_info.get(secret_k) or "").strip()
                    if len(sec_v) > 4:
                        msg = msg.replace(sec_v, "[REDACTED]")
        cur_ad_id = str(getattr(active_adapter, "account_id", "") or "").strip()
        if len(cur_ad_id) > 4 and cur_ad_id != DemoBrokerAdapter.DEMO_ACCOUNT_ID:
            msg = msg.replace(cur_ad_id, _mask_last4(cur_ad_id))
    except Exception:
        pass

    msg = re.sub(
        r'(["\'](?:accountNumber|account_id|accountId)["\']\s*:\s*["\'])([A-Za-z0-9_-]{5,})(["\'])',
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}{m.group(3)}",
        msg,
    )

    # Scrub /accounts/<hash> in HTTP exception URLs
    msg = re.sub(
        r"(/accounts/)([A-Za-z0-9_-]{5,})",
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}",
        msg,
    )
    # Scrub Bearer tokens and OAuth query/body parameters
    msg = re.sub(
        r"(Bearer\s+)[A-Za-z0-9._~+/=-]+",
        r"\1[REDACTED]",
        msg,
        flags=re.IGNORECASE,
    )
    msg = re.sub(
        r"((?:access_token|refresh_token|id_token|client_secret|app_secret|code)=)[^&\s'\"]+",
        r"\1[REDACTED]",
        msg,
        flags=re.IGNORECASE,
    )
    # Scrub JSON/dict serialized SDK auth headers (e.g. Webull x-access-token, x-signature)
    msg = re.sub(
        r'(["\'](?:x-access-token|x-signature|x-app-key|access_token|refresh_token|id_token|client_secret|app_secret|authorization)["\']\s*:\s*["\'])[^"\']+(["\'])',
        r"\1[REDACTED]\2",
        msg,
        flags=re.IGNORECASE,
    )
    # Ensure any order ID in cancel/order log lines is masked to last 4
    msg = re.sub(
        r"(order ID:\s*)(?!\.\.\.)([A-Za-z0-9_-]{5,})",
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}",
        msg,
        flags=re.IGNORECASE,
    )
    msg = re.sub(
        r"(Cancel response\s+)(?!\.\.\.)([A-Za-z0-9_-]{5,})(:)",
        lambda m: f"{m.group(1)}...{m.group(2)[-4:]}{m.group(3)}",
        msg,
        flags=re.IGNORECASE,
    )
    return msg


def sanitize_log_for_export(raw_log_text):
    """Produces a share-safe version of a session log with all total account
    balances/equities redacted ($[REDACTED]) while keeping all relative PnL
    (Realized, Open, Net, High, ratchets, and risk floors) intact."""
    lines = str(raw_log_text or "").splitlines()
    out_lines = []
    inserted_notice = False

    for line in lines:
        s = _scrub_log_line(line)
        # Redact total account equity / balance figures while keeping relative PnL
        s = re.sub(
            r"(Baseline anchored to:\s*)\$[0-9,]+(?:\.[0-9]{2})?",
            r"\1$[REDACTED]",
            s,
        )
        s = re.sub(
            r"(starting baseline from\s*)\$[0-9,]+(?:\.[0-9]{2})?(\s+to\s+)\$[0-9,]+(?:\.[0-9]{2})?",
            r"\1$[REDACTED]\2$[REDACTED]",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(
            r"((?:Start|Baseline|LastFlat|TotalAccountValue|NetLiq|Cash|MarketVal)=)\$[0-9,]+(?:\.[0-9]{2})?",
            r"\1$[REDACTED]",
            s,
        )
        s = re.sub(
            r"(session initialized at\s*)\$[0-9,]+(?:\.[0-9]{2})?",
            r"\1$[REDACTED]",
            s,
            flags=re.IGNORECASE,
        )
        out_lines.append(s)
        if not inserted_notice and s.startswith("==="):
            out_lines.append(
                "[SANITIZED EXPORT: Total account balances, user paths, "
                "and full order IDs redacted for safe sharing]"
            )
            inserted_notice = True

    return "\n".join(out_lines) + "\n"


def _sync_sanitized_log_archive():
    """Ensures every archived log in ~/enforcer_logs/ has a corresponding
    balance-redacted copy in ~/enforcer_logs/sanitized/enforcer_log_YYYY-MM-DD_sanitized.txt
    (retroactively backfilling any existing archived logs) and prunes files
    older than LOG_RETENTION_DAYS."""
    backfilled = 0
    try:
        os.makedirs(LOG_ARCHIVE_DIR, exist_ok=True)
        os.makedirs(SANITIZED_ARCHIVE_DIR, exist_ok=True)
    except Exception:
        return 0

    cutoff_dt = datetime.now() - timedelta(days=LOG_RETENTION_DAYS)
    cutoff_date_str = cutoff_dt.strftime("%Y-%m-%d")

    try:
        for fname in os.listdir(LOG_ARCHIVE_DIR):
            m = re.match(r"^enforcer_log_(\d{4}-\d{2}-\d{2})\.txt$", fname)
            if not m:
                continue
            date_part = m.group(1)
            raw_path = os.path.join(LOG_ARCHIVE_DIR, fname)
            if date_part < cutoff_date_str:
                continue
            san_fname = f"enforcer_log_{date_part}_sanitized.txt"
            san_path = os.path.join(SANITIZED_ARCHIVE_DIR, san_fname)
            needs_gen = not os.path.exists(san_path)
            if not needs_gen:
                try:
                    if os.path.getmtime(raw_path) > os.path.getmtime(san_path):
                        needs_gen = True
                except OSError:
                    pass
            if needs_gen:
                try:
                    with open(
                        raw_path, "r", encoding="utf-8", errors="replace"
                    ) as rf:
                        raw_txt = rf.read()
                    san_txt = sanitize_log_for_export(raw_txt)
                    with open(san_path, "w", encoding="utf-8") as sf:
                        sf.write(san_txt)
                    backfilled += 1
                except Exception:
                    pass
    except Exception:
        pass

    try:
        for s_fname in os.listdir(SANITIZED_ARCHIVE_DIR):
            m_s = re.match(
                r"^enforcer_log_(\d{4}-\d{2}-\d{2})_sanitized\.txt$", s_fname
            )
            if m_s and m_s.group(1) < cutoff_date_str:
                try:
                    os.remove(os.path.join(SANITIZED_ARCHIVE_DIR, s_fname))
                except Exception:
                    pass
    except Exception:
        pass

    return backfilled


_telemetry_auto_upload_in_flight = False


def _upload_sanitized_log_to_drive(
    filename, sanitized_text, active_broker, anonymous_id, extra_fields=None
) -> bool:
    """Uploads a balance-redacted session log (or bug report + log) to the Google Apps Script Drive
    webhook. Inspects the JSON response body so application-level errors
    (e.g., {"status": 413}) are never mistaken for HTTP 200 success."""
    import urllib.error
    import urllib.request

    try:
        payload_dict = {
            "filename": str(filename),
            "version": APP_VERSION,
            "broker": str(active_broker or "SCHWAB"),
            "tester_id": str(anonymous_id or ""),
            "content": str(sanitized_text or ""),
        }
        if isinstance(extra_fields, dict):
            for ek, ev in extra_fields.items():
                if ek not in payload_dict and ev is not None:
                    payload_dict[ek] = ev
        payload_bytes = json.dumps(payload_dict).encode("utf-8")
        req = urllib.request.Request(
            BETA_TELEMETRY_WEBHOOK_URL,
            data=payload_bytes,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            code = getattr(resp, "status", None) or resp.getcode()
            body_raw = ""
            try:
                body_raw = resp.read().decode("utf-8", errors="replace").strip()
            except Exception:
                pass
            if body_raw.startswith("{"):
                try:
                    body_json = json.loads(body_raw)
                    app_status = int(body_json.get("status", 200) or 200)
                    if app_status >= 400 or body_json.get("error"):
                        return False
                except Exception:
                    pass
            return code == 200 or (200 <= int(code or 0) < 300)
    except urllib.error.HTTPError as he:
        code = int(getattr(he, "code", 0) or 0)
        err_url = str(getattr(he, "url", "") or "").lower()
        loc_hdr = ""
        try:
            if getattr(he, "headers", None) is not None:
                loc_hdr = str(he.headers.get("Location", "") or "").lower()
        except Exception:
            pass
        if code == 200:
            return True
        if code in (302, 405) and (
            "googleusercontent.com" in err_url
            or "googleusercontent.com" in loc_hdr
        ):
            return True
        return False
    except Exception:
        return False


def _find_most_recent_prior_sanitized_log():
    """Returns (filename, full_path) for the most recent prior-day sanitized log
    in ~/enforcer_logs/sanitized/ (where YYYY-MM-DD < get_today_str()), or
    (None, None) if none exists."""
    today_str = get_today_str()
    best_date = ""
    best_fname = None
    best_path = None
    try:
        if not os.path.isdir(SANITIZED_ARCHIVE_DIR):
            return None, None
        for s_fname in os.listdir(SANITIZED_ARCHIVE_DIR):
            m_s = re.match(
                r"^enforcer_log_(\d{4}-\d{2}-\d{2})_sanitized\.txt$", s_fname
            )
            if not m_s:
                continue
            d_part = m_s.group(1)
            if d_part < today_str and d_part > best_date:
                cand_path = os.path.join(SANITIZED_ARCHIVE_DIR, s_fname)
                try:
                    if os.path.isfile(cand_path) and os.path.getsize(cand_path) > 0:
                        best_date = d_part
                        best_fname = s_fname
                        best_path = cand_path
                except OSError:
                    pass
    except Exception:
        return None, None
    return best_fname, best_path


def _maybe_upload_prior_day_sanitized_log():
    """Non-blocking startup auto-uploader: if auto_share_sanitized_logs is True,
    checks for the most recent prior-day sanitized log in ~/enforcer_logs/sanitized/
    and uploads it in a background daemon thread if not already uploaded."""
    global _telemetry_auto_upload_in_flight
    try:
        if _telemetry_auto_upload_in_flight:
            return
        if not config.get("auto_share_sanitized_logs", False):
            return
        fname, fpath = _find_most_recent_prior_sanitized_log()
        if not fname or not fpath:
            return
        if fname == config.get("last_uploaded_sanitized_log", ""):
            return
        with open(fpath, "r", encoding="utf-8", errors="replace") as f:
            san_text = f.read()
        if not san_text.strip():
            return

        tester_id = str(config.get("anonymous_tester_id", "") or "").strip()
        if not tester_id:
            tester_id = uuid.uuid4().hex[:6]
            config["anonymous_tester_id"] = tester_id
            save_config(config)
        active_b = str(config.get("active_broker", "SCHWAB") or "SCHWAB")
        _telemetry_auto_upload_in_flight = True

        def _bg_upload():
            global _telemetry_auto_upload_in_flight
            try:
                ok = _upload_sanitized_log_to_drive(
                    fname, san_text, active_b, tester_id
                )
                if ok:
                    config["last_uploaded_sanitized_log"] = fname
                    save_config(config)
                    log_event(
                        "TELEMETRY",
                        f"Auto-shared prior-day sanitized log "
                        f"({fname}, Tester ID: {tester_id})",
                    )
            except Exception:
                pass
            finally:
                _telemetry_auto_upload_in_flight = False

        threading.Thread(target=_bg_upload, daemon=True).start()
    except Exception:
        _telemetry_auto_upload_in_flight = False


def _get_os_env_summary():
    py_ver = sys.version.split()[0]
    try:
        wv = sys.getwindowsversion()
        os_lbl = "Win11" if wv.build >= 22000 else f"Win{wv.major}"
        os_str = f"{os_lbl}(Build {wv.build})"
    except Exception:
        os_str = sys.platform
    return f"OS={os_str} | Py={py_ver}"


def init_daily_log():
    today_str = get_today_str()
    env_info = _get_os_env_summary()
    header_line = (
        f"=== ENFORCER SESSION LOG | v{APP_VERSION} | DATE: {today_str} | {env_info} ===\n"
    )
    needs_wipe = True

    if os.path.exists(LOG_PATH):
        try:
            with open(LOG_PATH, "r", encoding="utf-8") as f:
                first_line = f.readline()
                if today_str in first_line:
                    needs_wipe = False
        except Exception:
            needs_wipe = True

    try:
        if needs_wipe:
            archived_path, pruned_cnt = _archive_previous_log_and_prune(today_str)
            _sync_sanitized_log_archive()
            with open(LOG_PATH, "w", encoding="utf-8") as f:
                f.write(header_line)
                f.write(f"Log File Path: {_mask_user_path(LOG_PATH)}\n")
                f.write(
                    f"Archive Folder ({LOG_RETENTION_DAYS}-day retention): "
                    f"{_mask_user_path(LOG_ARCHIVE_DIR)}\n" + "=" * 50 + "\n"
                )
            log_event(
                "SESSION",
                f"Initialized fresh daily log file (v{APP_VERSION} | {env_info})."
            )
            if archived_path:
                log_event(
                    "SESSION",
                    f"Archived previous session log to: {_mask_user_path(archived_path)}"
                )
            if pruned_cnt > 0:
                log_event(
                    "SESSION",
                    f"Pruned {pruned_cnt} archived log(s) older than "
                    f"{LOG_RETENTION_DAYS} days."
                )
        else:
            _sync_sanitized_log_archive()
            log_event(
                "SESSION",
                f"--- APPLICATION LAUNCHED / RESUMED (v{APP_VERSION} | {env_info}) ---"
            )
        load_config(log_restore=False)
        _maybe_upload_prior_day_sanitized_log()
    except Exception as e:
        try:
            print(f"Could not initialize log file: {e}")
        except Exception:
            pass


def log_event(category, message):
    ts = datetime.now().strftime("%H:%M:%S.%f")[:-3]
    clean_msg = _scrub_log_line(message)
    line = f"[{ts}] [{category:<10}] {clean_msg}"
    try:
        print(line)
    except Exception:
        pass
    with log_lock:
        try:
            with open(LOG_PATH, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        except Exception as e:
            try:
                print(f"Log write error: {e}")
            except Exception:
                pass


def _custom_showwarning(message, category, filename, lineno, file=None, line=None):
    short_file = os.path.basename(str(filename)) if filename else "unknown"
    cat_name = getattr(category, "__name__", str(category))
    msg_clean = str(message).strip().replace("\n", " ")
    if cat_name == "AuthlibDeprecationWarning" or "httpx2" in msg_clean:
        return
    log_event("PY_WARN", f"{cat_name} ({short_file}:{lineno}): {msg_clean}")


class _EnforcerFileLogHandler(logging.Handler):
    def __init__(self):
        super().__init__(level=logging.WARNING)
        self._in_emit = False

    def emit(self, record):
        if self._in_emit:
            return
        try:
            self._in_emit = True
            msg = record.getMessage().strip().replace("\n", " ")
            if msg:
                log_event("LIB_WARN", f"{record.name} ({record.levelname}): {msg}")
        except Exception:
            pass
        finally:
            self._in_emit = False


class _StderrToLogTee:
    """Tees any raw stderr output (such as Tcl/Tk C-level 'after' script errors
    or C-extension messages) into enforcer_log.txt while preserving console stderr."""

    def __init__(self, orig_stderr):
        self._orig = orig_stderr
        self._buf = ""
        self._in_write = False

    def write(self, data):
        if self._orig is not None:
            try:
                self._orig.write(data)
            except Exception:
                pass
        if self._in_write or not data:
            return
        try:
            self._in_write = True
            self._buf += str(data)
            while "\n" in self._buf:
                line, self._buf = self._buf.split("\n", 1)
                clean = line.strip()
                if clean and not re.match(r"^\[\d{2}:\d{2}:\d{2}\.\d{3}\]", clean):
                    ts = datetime.now().strftime("%H:%M:%S.%f")[:-3]
                    scrubbed = _scrub_log_line(clean)
                    entry = f"[{ts}] [{'STDERR':<10}] {scrubbed}"
                    with log_lock:
                        try:
                            with open(LOG_PATH, "a", encoding="utf-8") as f:
                                f.write(entry + "\n")
                        except Exception:
                            pass
        except Exception:
            pass
        finally:
            self._in_write = False

    def flush(self):
        if self._orig is not None:
            try:
                self._orig.flush()
            except Exception:
                pass

    def __getattr__(self, name):
        return getattr(self._orig, name)


def _install_tcl_bgerror_hook(tk_obj):
    """Routes C-level Tcl background/event errors into enforcer_log.txt."""
    try:
        def _tcl_bgerror(msg):
            try:
                err_info = str(tk_obj.tk.globalgetvar("errorInfo") or "").strip()
            except Exception:
                err_info = ""
            detail = err_info or str(msg or "")
            # Ignore benign orphaned Tkinter after/after_idle callbacks whose
            # widget was destroyed right before the scheduled timer fired.
            if "invalid command name" in detail and '("after" script)' in detail:
                return
            flat = " | ".join(ln.strip() for ln in detail.splitlines() if ln.strip())
            if flat:
                log_event("TCL_ERR", flat)

        tk_obj.createcommand("bgerror", _tcl_bgerror)
    except Exception:
        pass


_crash_rollback_prompted = False


def _get_prev_enforcer_path():
    return os.path.join(SCRIPT_DIR, "enforcer.py.prev")


def _get_prev_changelog_path():
    return os.path.join(SCRIPT_DIR, "CHANGELOG.md.prev")


def _get_boot_pending_path():
    return os.path.join(SCRIPT_DIR, ".enforcer_boot_pending.json")


def _validate_enforcer_source_bytes(raw_bytes):
    """Validates candidate enforcer.py / enforcer.py.prev bytes for UTF-8
    integrity, core entrypoint markers, APP_VERSION header, and Python syntax.
    Returns (ok, parsed_version, error_reason)."""
    if not isinstance(raw_bytes, (bytes, bytearray)) or len(raw_bytes) < 512:
        return False, "", "Backup file is empty or truncated."
    try:
        src_txt = bytes(raw_bytes).decode("utf-8")
    except UnicodeDecodeError:
        return False, "", "Backup file failed UTF-8 decoding."
    if "\x00" in src_txt:
        return False, "", "Backup file contains null bytes."
    if (
        "def data_loop" not in src_txt
        or 'if __name__ == "__main__":' not in src_txt
    ):
        return False, "", "Backup file is missing core PnL Enforcer entrypoints."
    m_ver = re.search(
        r'(?m)^APP_VERSION\s*=\s*["\']([^"\']+)["\']', src_txt
    )
    if not m_ver or not m_ver.group(1).strip():
        return False, "", "Backup file is missing APP_VERSION."
    parsed_ver = m_ver.group(1).strip()
    try:
        compile(src_txt, "enforcer.py.prev", "exec")
    except Exception as exc:
        return False, "", f"Backup failed Python syntax check ({exc})."
    return True, parsed_ver, ""


_ROLLBACK_INFO_CACHE = {"key": None, "val": None}
_rollback_cfg_fallback_lock = threading.RLock()


def get_rollback_backup_info():
    """Inspects enforcer.py.prev in SCRIPT_DIR and returns metadata dict:
    {available, reason, prev_version, mtime_str, same_version, prev_path}.
    Memoized by (path, st_mtime_ns, st_size, APP_VERSION) so UI menus/dialogs
    never recompile 37k+ lines repeatedly on the main thread."""
    prev_py = _get_prev_enforcer_path()
    if not os.path.isfile(prev_py):
        _ROLLBACK_INFO_CACHE["key"] = None
        _ROLLBACK_INFO_CACHE["val"] = None
        return {
            "available": False,
            "reason": "NO_BACKUP",
            "prev_version": "",
            "mtime_str": "",
            "same_version": False,
            "prev_path": prev_py,
        }
    try:
        st = os.stat(prev_py)
        cache_key = (
            prev_py,
            getattr(st, "st_mtime_ns", st.st_mtime),
            int(st.st_size),
            str(APP_VERSION),
        )
        if (
            _ROLLBACK_INFO_CACHE.get("key") == cache_key
            and isinstance(_ROLLBACK_INFO_CACHE.get("val"), dict)
        ):
            return dict(_ROLLBACK_INFO_CACHE["val"])
        mtime_str = datetime.fromtimestamp(st.st_mtime).strftime(
            "%Y-%m-%d %I:%M %p"
        )
        with open(prev_py, "rb") as pf_in:
            raw_b = pf_in.read()
    except Exception as exc:
        return {
            "available": False,
            "reason": "CORRUPT_BACKUP",
            "prev_version": "",
            "mtime_str": "",
            "same_version": False,
            "prev_path": prev_py,
            "detail": str(exc),
        }
    ok_src, prev_ver, err_msg = _validate_enforcer_source_bytes(raw_b)
    if not ok_src:
        res_d = {
            "available": False,
            "reason": "CORRUPT_BACKUP",
            "prev_version": "",
            "mtime_str": mtime_str,
            "same_version": False,
            "prev_path": prev_py,
            "detail": err_msg,
        }
    elif prev_ver == APP_VERSION:
        res_d = {
            "available": False,
            "reason": "SAME_VERSION",
            "prev_version": prev_ver,
            "mtime_str": mtime_str,
            "same_version": True,
            "prev_path": prev_py,
        }
    else:
        res_d = {
            "available": True,
            "reason": "OK",
            "prev_version": prev_ver,
            "mtime_str": mtime_str,
            "same_version": False,
            "prev_path": prev_py,
        }
    _ROLLBACK_INFO_CACHE["key"] = cache_key
    _ROLLBACK_INFO_CACHE["val"] = dict(res_d)
    return res_d


def _peek_saved_skipped_update_version():
    """Reads skipped_update_version from CONFIG_PATH / loaded config."""
    io_lk = globals().get("_config_io_lock") or _rollback_cfg_fallback_lock
    with io_lk:
        try:
            if os.path.isfile(CONFIG_PATH):
                with open(CONFIG_PATH, "r", encoding="utf-8") as cf:
                    disk_cfg = json.load(cf)
                if isinstance(disk_cfg, dict):
                    return str(
                        disk_cfg.get("skipped_update_version", "") or ""
                    ).strip()
        except Exception:
            pass
        try:
            mem_cfg = globals().get("config")
            if isinstance(mem_cfg, dict):
                return str(
                    mem_cfg.get("skipped_update_version", "") or ""
                ).strip()
        except Exception:
            pass
    return ""


def _record_skipped_update_version_on_disk(ver_str):
    """Thread-safely updates ONLY skipped_update_version inside CONFIG_PATH on
    disk under _config_io_lock (preserving 100% of existing settings, tokens,
    locks, and baselines even if called before load_config() during early startup
    crash recovery without racing concurrent save_config() calls)."""
    clean_v = str(ver_str or "").strip()
    io_lk = globals().get("_config_io_lock") or _rollback_cfg_fallback_lock
    with io_lk:
        mem_cfg = globals().get("config")
        if isinstance(mem_cfg, dict):
            mem_cfg["skipped_update_version"] = clean_v
        if not os.path.isfile(CONFIG_PATH):
            return
        try:
            with open(CONFIG_PATH, "r", encoding="utf-8") as cf:
                disk_cfg = json.load(cf)
            if not isinstance(disk_cfg, dict):
                return
            if (
                str(disk_cfg.get("skipped_update_version", "") or "").strip()
                == clean_v
            ):
                return
            disk_cfg["skipped_update_version"] = clean_v
            tmp_cfg_p = f"{CONFIG_PATH}.{os.getpid()}.rb.tmp"
            with open(tmp_cfg_p, "w", encoding="utf-8") as wf:
                json.dump(disk_cfg, wf, indent=4)
                wf.flush()
                os.fsync(wf.fileno())
            os.replace(tmp_cfg_p, CONFIG_PATH)
        except Exception:
            pass


def _mark_boot_pending_bat_prompt_suppressed():
    """Marks .enforcer_boot_pending.json with suppress_bat_prompt=True (when the
    user declines the crash prompt or declines the liability waiver) WITHOUT
    deleting the marker, so an unconfirmed build can still never overwrite a
    known-good enforcer.py.prev backup on a subsequent update."""
    bp_path = _get_boot_pending_path()
    if not os.path.isfile(bp_path):
        return
    try:
        with open(bp_path, "r", encoding="utf-8") as rf:
            bp_d = json.load(rf)
        if not isinstance(bp_d, dict):
            return
        bp_d["suppress_bat_prompt"] = True
        tmp_bp = f"{bp_path}.{os.getpid()}.sup.tmp"
        with open(tmp_bp, "w", encoding="utf-8") as wf:
            json.dump(bp_d, wf, indent=2)
            wf.flush()
            os.fsync(wf.fileno())
        os.replace(tmp_bp, bp_path)
    except Exception:
        pass


def _restore_prev_files_to_disk():
    """Atomically copies verified enforcer.py.prev -> enforcer.py (and
    CHANGELOG.md.prev -> CHANGELOG.md if present) while keeping .prev intact on
    disk, and clears .enforcer_boot_pending.json. Returns (ok, prev_ver)."""
    prev_py = _get_prev_enforcer_path()
    if not os.path.isfile(prev_py):
        return False, ""
    try:
        with open(prev_py, "rb") as pf_in:
            prev_bytes = pf_in.read()
        ok_src, prev_ver, _err = _validate_enforcer_source_bytes(prev_bytes)
        if not ok_src:
            return False, ""
        target_py = os.path.join(SCRIPT_DIR, "enforcer.py")
        tmp_py = f"{target_py}.{os.getpid()}.rb.tmp"
        with open(tmp_py, "wb") as out_f:
            out_f.write(prev_bytes)
            out_f.flush()
            os.fsync(out_f.fileno())
        os.replace(tmp_py, target_py)

        prev_cl = _get_prev_changelog_path()
        if os.path.isfile(prev_cl):
            try:
                with open(prev_cl, "rb") as clf_in:
                    cl_b = clf_in.read()
                if cl_b:
                    target_cl = os.path.join(SCRIPT_DIR, "CHANGELOG.md")
                    tmp_cl = f"{target_cl}.{os.getpid()}.rb.tmp"
                    with open(tmp_cl, "wb") as clf_out:
                        clf_out.write(cl_b)
                    os.replace(tmp_cl, target_cl)
            except Exception:
                pass

        bp_path = _get_boot_pending_path()
        if os.path.exists(bp_path):
            try:
                os.remove(bp_path)
            except Exception:
                pass
        return True, prev_ver
    except Exception:
        return False, ""


def _clear_boot_pending_marker():
    """Clears .enforcer_boot_pending.json once Pre-Flight has successfully opened
    (confirming the newly installed update booted cleanly)."""
    bp_path = _get_boot_pending_path()
    if not os.path.exists(bp_path):
        return False
    try:
        os.remove(bp_path)
        log_event(
            "SESSION",
            f"Confirmed clean startup on updated build v{APP_VERSION}.",
        )
        return True
    except Exception:
        return False


def _offer_crash_boot_rollback(err_summary, allow_in_test=False):
    """Win32 crash-safe fallback: if a newly installed update (.enforcer_boot_pending.json
    still present) throws a fatal startup exception before Pre-Flight opens, pops a
    native Win32 MessageBoxW offering 1-click restore to enforcer.py.prev without
    needing Tkinter."""
    global _crash_rollback_prompted
    if _crash_rollback_prompted:
        return False
    if not allow_in_test and not (
        globals().get("_IS_MAIN_PROCESS", False) or __name__ == "__main__"
    ):
        return False
    bp_path = _get_boot_pending_path()
    if not os.path.exists(bp_path):
        return False
    rb_info = get_rollback_backup_info()
    if not rb_info.get("available"):
        return False
    _crash_rollback_prompted = True
    prev_ver = rb_info["prev_version"]
    short_err = str(err_summary or "Unknown startup error").strip()
    if len(short_err) > 260:
        short_err = short_err[:257] + "..."
    prompt_txt = (
        f"PnL Enforcer v{APP_VERSION} hit a startup error before opening Pre-Flight:\n\n"
        f"{short_err}\n\n"
        f"Restore your previous working version (v{prev_ver}) and relaunch now?\n\n"
        "(Your saved settings, broker tokens, and session baseline stay untouched.)"
    )
    try:
        t_ans = os.environ.get("ENFORCER_TEST_RECOVERY_ANS", "").strip()
        if t_ans:
            ans = int(t_ans)
        else:
            # MB_YESNO (0x04) | MB_ICONWARNING (0x30) | MB_TOPMOST (0x40000)
            ans = ctypes.windll.user32.MessageBoxW(
                0,
                prompt_txt,
                "PnL Enforcer — Startup Recovery",
                0x00040034,
            )
    except Exception:
        return False

    if ans == 6:  # IDYES
        ok_rb, restored_v = _restore_prev_files_to_disk()
        if ok_rb:
            _record_skipped_update_version_on_disk(APP_VERSION)
            log_event(
                "SESSION",
                f"Crash-recovery rollback restored v{restored_v} after failed v{APP_VERSION} boot.",
            )
            if allow_in_test:
                return True
            rel_fn = globals().get("_release_single_instance_mutex")
            if callable(rel_fn):
                rel_fn()
            spawn_fn = globals().get("_spawn_updated_enforcer")
            target_py = os.path.join(SCRIPT_DIR, "enforcer.py")
            if callable(spawn_fn):
                spawn_fn(target_py)
            try:
                subprocess.Popen([sys.executable, target_py])
            except Exception:
                pass
            sys.exit(0)
    elif ans == 7:  # IDNO — keep boot_pending marker so .prev stays protected, suppress bat repeat prompt
        _mark_boot_pending_bat_prompt_suppressed()
    return False


def _install_global_error_hooks():
    """Routes all uncaught main-thread, background-thread, Tkinter callback,
    Tcl background errors, and stderr messages into enforcer_log.txt."""
    warnings.showwarning = _custom_showwarning
    logging.getLogger().addHandler(_EnforcerFileLogHandler())
    if not isinstance(sys.stderr, _StderrToLogTee):
        sys.stderr = _StderrToLogTee(sys.stderr)

    def _handle_uncaught(exc_type, exc_value, exc_tb):
        if issubclass(exc_type, (KeyboardInterrupt, SystemExit)):
            sys.__excepthook__(exc_type, exc_value, exc_tb)
            return
        tb_str = " | ".join(
            ln.strip()
            for ln in traceback.format_exception(exc_type, exc_value, exc_tb)
            if ln.strip()
        )
        log_event("UNCAUGHT", tb_str)
        _offer_crash_boot_rollback(f"{exc_type.__name__}: {exc_value}")

    def _handle_thread_uncaught(args):
        if issubclass(args.exc_type, (KeyboardInterrupt, SystemExit)):
            return
        t_name = getattr(args.thread, "name", "Thread")
        tb_str = " | ".join(
            ln.strip()
            for ln in traceback.format_exception(
                args.exc_type, args.exc_value, args.exc_traceback
            )
            if ln.strip()
        )
        log_event("THRD_ERR", f"[{t_name}] {tb_str}")

    def _handle_tk_callback_exc(self, exc_type, exc_value, exc_tb):
        tb_str = " | ".join(
            ln.strip()
            for ln in traceback.format_exception(exc_type, exc_value, exc_tb)
            if ln.strip()
        )
        log_event("TK_ERROR", tb_str)

    sys.excepthook = _handle_uncaught
    if hasattr(threading, "excepthook"):
        threading.excepthook = _handle_thread_uncaught
    tk.Tk.report_callback_exception = _handle_tk_callback_exc
    if not getattr(tk.Tk, "_enforcer_bgerror_hooked", False):
        _orig_tk_init = tk.Tk.__init__

        def _hooked_tk_init(self, *args, **kwargs):
            _orig_tk_init(self, *args, **kwargs)
            _install_tcl_bgerror_hook(self)

        tk.Tk.__init__ = _hooked_tk_init
        tk.Tk._enforcer_bgerror_hooked = True


if __name__ == "__main__":
    _install_global_error_hooks()


def format_config_summary(cfg):
    broker = cfg.get("active_broker", "SCHWAB")
    cd_str = (
        f"ON({cfg.get('open_cooldown_mins', 1):g}m)"
        if cfg.get("enable_open_cooldown") else "OFF"
    )
    tilt_str = (
        f"ON({int(cfg.get('consec_loss_count', 3))}L/"
        f"{cfg.get('consec_loss_window_mins', 15):g}m, "
        f"Loss<=-${abs(float(cfg.get('consec_loss_min_dollars', 25))):,.0f}, "
        f"WinRst>=+${abs(float(cfg.get('consec_win_reset_dollars', 10))):,.0f})"
        if cfg.get("enable_consec_loss_cooldown") else "OFF"
    )
    dl_mins = cfg.get("daily_lock_mins", 15.0)
    dl_str = (
        f"ON({dl_mins:g}m)" if dl_mins > 0 else "ON(Once)"
    ) if cfg.get("enable_lock_os") else "OFF"
    eh_lock_str = (
        f"ON(+${cfg.get('pm_lock_trigger', 500):,.0f}/Trail:${cfg.get('pm_trail_cushion', 500):,.0f})"
        if cfg.get("enable_pm_lock", True)
        else "OFF"
    )
    t2_str = (
        f"ON(+${cfg.get('t2_trigger', 250):,.0f}->${cfg.get('t2_max_loss', -1000):+,.0f})"
        if cfg.get("enable_t2", True)
        else "OFF"
    )
    t3_str = (
        f"ON(+${cfg.get('t3_trigger', 500):,.0f}->${cfg.get('t3_max_loss', -500):+,.0f})"
        if cfg.get("enable_t3", True)
        else "OFF"
    )
    t4_str = (
        f"ON(+${cfg.get('t4_trigger', 1000):,.0f}/Trail:${cfg.get('t4_trail', 500):,.0f})"
        if cfg.get("enable_t4", True)
        else "OFF"
    )

    return (
        f"Broker={broker} | Cols={len(get_active_hud_columns(cfg))} | "
        f"Poll={cfg.get('poll_interval')}s | "
        f"AlarmsOnly={'ON' if cfg.get('alarms_only_mode') else 'OFF'} | "
        f"OpenStop={'ON' if cfg.get('enable_open_flatten') else 'OFF'}"
        f"(-${cfg.get('open_max_loss', 0):,.0f}, CoolDown={cd_str}) | "
        f"TiltStop={tilt_str} | "
        f"DayFlat={'ON' if cfg.get('enable_auto_flatten') else 'OFF'} | "
        f"OptFlat={'ON(BETA)' if is_options_flatten_armed(cfg) else 'OFF'} | "
        f"KillTOS={'ON' if cfg.get('enable_kill_tos') else 'OFF'} | "
        f"KillWB={'ON' if cfg.get('enable_kill_webull') else 'OFF'} | "
        f"LockOS={dl_str} | "
        f"SilentMode={'ON' if cfg.get('mute_all_audio', False) else 'OFF'} | "
        f"Voice={'ON' if cfg.get('enable_voice_cues', True) else 'OFF'} | "
        f"UpChime={'ON' if cfg.get('enable_upside_chime', True) else 'OFF'} | "
        f"ResetSwitch={'ON' if cfg.get('reset_at_925', True) else 'OFF'} | "
        f"IgnorePrePos={'ON' if cfg.get('ignore_preexisting_positions', True) else 'OFF'} | "
        f"EH_Max=-${cfg.get('pm_max_loss', 0):,.0f} | "
        f"EH_Lock={eh_lock_str} | "
        f"T1_Max=-${cfg.get('t1_max_loss', 0):,.0f} | "
        f"T2={t2_str} | T3={t3_str} | T4={t4_str}"
    )


def restore_account_session(broker_name, account_id, log_restore=False):
    """Restores today's saved baseline for a specific broker + account_id.
    Returns True if a valid baseline for today was found, False otherwise."""
    global start_equity, max_equity, daily_max_equity, daily_min_equity
    global last_flat_equity, anchor_cash_flow, _last_logged_unanchored_cash_flow
    global has_reset_at_open, has_reset_at_close, is_locked_down
    global done_for_today, committed_for_today
    global win_trades, loss_trades, prev_flat_realized_pnl
    global settled_realized_pnl, flat_desync_streak
    global in_trade_desync_streak, pending_scale_out_tol
    global current_upside_tier, first_poll_of_launch, _launch_fee_drift_checked
    global _restored_session_saved_epoch, _restored_session_was_flat
    global _off_session_reconciled, _cold_launch_ignored_qty_mutated
    global recent_loss_timestamps, ignored_positions, pending_halt_breach
    global active_non_breach_halted_syms, _notified_non_breach_halt_syms
    global active_session_date

    _launch_fee_drift_checked = False
    _restored_session_saved_epoch = 0.0
    _restored_session_was_flat = True
    _off_session_reconciled = False
    _cold_launch_ignored_qty_mutated = False
    recent_loss_timestamps.clear()
    ignored_positions.clear()
    pending_halt_breach = None
    active_non_breach_halted_syms.clear()
    _notified_non_breach_halt_syms.clear()
    flat_desync_streak = 0
    in_trade_desync_streak = 0
    pending_scale_out_tol = 0.0
    today_str = get_today_str()
    active_session_date = today_str
    s_key = get_session_key(broker_name, account_id)
    acct_sessions = (
        _demo_memory_session
        if str(broker_name).upper() == "DEMO"
        else config.get("account_sessions", {})
    )

    if s_key and s_key in acct_sessions:
        s_data = acct_sessions[s_key]
        s_start = s_data.get("start_equity")
        if (
            s_data.get("session_date") == today_str
            and s_start is not None
            and float(s_start) > 0.0
        ):
            start_equity = float(s_start)
            max_equity = float(s_data.get("max_equity") or start_equity)
            daily_max_equity = float(
                s_data.get("daily_max_equity") or max_equity
            )
            last_flat_equity = float(
                s_data.get("last_flat_equity") or start_equity
            )
            s_min = s_data.get("daily_min_equity")
            if s_min is not None and float(s_min) > 0.0:
                daily_min_equity = min(
                    float(s_min), start_equity, last_flat_equity
                )
            elif str(broker_name).upper() == "DEMO":
                daily_min_equity = min(start_equity, last_flat_equity)
            else:
                bf_min = backfill_min_pnl_from_today_log(
                    broker_name, start_equity
                )
                daily_min_equity = min(
                    start_equity,
                    last_flat_equity,
                    round(start_equity + bf_min, 2),
                )
            _restored_session_saved_epoch = float(
                s_data.get("last_saved_epoch") or 0.0
            )
            _restored_session_was_flat = bool(
                s_data.get("was_flat_at_save", True)
            )
            anchor_cash_flow = float(
                s_data.get("anchor_cash_flow", 0.0) or 0.0
            )
            has_reset_at_open = bool(
                s_data.get("has_reset_at_open", False)
            )
            has_reset_at_close = bool(
                s_data.get("has_reset_at_close", False)
            )
            is_locked_down = bool(
                s_data.get("is_locked_down", False)
                and s_data.get("breach_date") == today_str
            )
            done_for_today = bool(
                s_data.get("done_for_today", False)
                and s_data.get("done_for_today_date") == today_str
            )
            committed_for_today = bool(
                (
                    s_data.get("committed_for_today", False)
                    and s_data.get("committed_date") == today_str
                )
                or (
                    str(broker_name).upper() != "DEMO"
                    and str(config.get("committed_session_date", "")) == today_str
                    and str(config.get("committed_broker", "") or "").upper()
                    in ("SCHWAB", "WEBULL", "")
                )
            )
            win_trades = int(s_data.get("win_trades", 0) or 0)
            loss_trades = int(s_data.get("loss_trades", 0) or 0)
            saved_lts = s_data.get("loss_timestamps")
            if isinstance(saved_lts, list):
                now_ts = time.time()
                win_sec = max(
                    0.5, float(config.get("consec_loss_window_mins", 15.0))
                ) * 60.0
                recent_loss_timestamps.extend(
                    float(t)
                    for t in saved_lts
                    if isinstance(t, (int, float))
                    and 0.0 <= (now_ts - float(t)) < win_sec
                )
            saved_ig = s_data.get("ignored_positions")
            if isinstance(saved_ig, dict):
                ignored_positions.update(json.loads(json.dumps(saved_ig)))
            prev_flat_realized_pnl = round(last_flat_equity - start_equity, 2)
            settled_realized_pnl = prev_flat_realized_pnl
            if (
                "win_trades" not in s_data
                and win_trades == 0
                and loss_trades == 0
                and str(broker_name).upper() != "DEMO"
            ):
                bw, bl, _ = backfill_trades_from_today_log(broker_name)
                if bw > 0 or bl > 0:
                    win_trades, loss_trades = bw, bl
            current_upside_tier = compute_upside_tier(
                is_rth(), round(max_equity - start_equity, 2), config
            )
            first_poll_of_launch = True
            if log_restore:
                ig_note = (
                    f" | IgnoredPreExisting={list(ignored_positions.keys())}"
                    if ignored_positions
                    else ""
                )
                _, st_pnl, _, tier_short, _, _ = describe_active_floor(config)
                log_event(
                    "SESSION",
                    f"Restored {broker_name} baseline from memory: "
                    f"Start=${start_equity:,.2f} | "
                    f"LastFlat=${last_flat_equity:,.2f} | "
                    f"RulebookHWM={format_dollar(max_equity - start_equity)} | "
                    f"SessionHighPnL={format_dollar(daily_max_equity - start_equity)} | "
                    f"SessionLowPnL={format_dollar(daily_min_equity - start_equity)} | "
                    f"ActiveStop={format_dollar(st_pnl)} ({tier_short}) | "
                    f"{format_trades_wl_inline(win_trades, loss_trades)}{ig_note}"
                )
            return True

    # Backward-compatible check for legacy top-level saved session fields
    saved_start = config.get("saved_start_equity")
    if (
        str(broker_name).upper() != "DEMO"
        and config.get("session_date") == today_str
        and saved_start is not None
        and float(saved_start) > 0.0
        and config.get("saved_account_id") == account_id
        and account_id != ""
    ):
        start_equity = float(saved_start)
        max_equity = float(config.get("saved_max_equity") or start_equity)
        daily_max_equity = float(
            config.get("saved_daily_max_equity") or max_equity
        )
        last_flat_equity = float(
            config.get("saved_last_flat_equity") or start_equity
        )
        bf_min = backfill_min_pnl_from_today_log(broker_name, start_equity)
        daily_min_equity = min(
            start_equity,
            last_flat_equity,
            round(start_equity + bf_min, 2),
        )
        has_reset_at_open = bool(config.get("saved_has_reset_at_open", False))
        has_reset_at_close = bool(config.get("saved_has_reset_at_close", False))
        is_locked_down = False
        done_for_today = False
        committed_for_today = bool(
            str(config.get("committed_session_date", "")) == today_str
            and str(config.get("committed_broker", "") or "").upper()
            in ("SCHWAB", "WEBULL", "")
        )
        win_trades = int(config.get("saved_win_trades", 0) or 0)
        loss_trades = int(config.get("saved_loss_trades", 0) or 0)
        prev_flat_realized_pnl = round(last_flat_equity - start_equity, 2)
        settled_realized_pnl = prev_flat_realized_pnl
        if win_trades == 0 and loss_trades == 0:
            bw, bl, _ = backfill_trades_from_today_log(broker_name)
            if bw > 0 or bl > 0:
                win_trades, loss_trades = bw, bl
        current_upside_tier = compute_upside_tier(
            is_rth(), round(max_equity - start_equity, 2), config
        )
        first_poll_of_launch = True
        if log_restore:
            _, st_pnl, _, tier_short, _, _ = describe_active_floor(config)
            log_event(
                "SESSION",
                f"Restored {broker_name} baseline from memory: "
                f"Start=${start_equity:,.2f} | "
                f"LastFlat=${last_flat_equity:,.2f} | "
                f"RulebookHWM={format_dollar(max_equity - start_equity)} | "
                f"SessionHighPnL={format_dollar(daily_max_equity - start_equity)} | "
                f"SessionLowPnL={format_dollar(daily_min_equity - start_equity)} | "
                f"ActiveStop={format_dollar(st_pnl)} ({tier_short}) | "
                f"{format_trades_wl_inline(win_trades, loss_trades)}"
            )
        return True

    start_equity = None
    max_equity = None
    daily_max_equity = None
    daily_min_equity = None
    last_flat_equity = None
    anchor_cash_flow = 0.0
    has_reset_at_open = False
    has_reset_at_close = False
    is_locked_down = False
    done_for_today = False
    committed_for_today = bool(
        str(broker_name).upper() != "DEMO"
        and str(config.get("committed_session_date", "")) == today_str
        and str(config.get("committed_broker", "") or "").upper()
        in ("SCHWAB", "WEBULL", "")
    )
    win_trades = 0
    loss_trades = 0
    prev_flat_realized_pnl = 0.0
    settled_realized_pnl = None
    current_upside_tier = 1
    first_poll_of_launch = True
    return False


def _load_json_dict_from_file(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("Config root is not a JSON object")
    return data


def load_config(log_restore=False):
    global config, _is_existing_user_install, _config_load_corrupt
    global _last_real_broker, committed_for_today
    with _config_io_lock:
        bak_path = CONFIG_PATH + ".bak"
        saved = None
        recovered_from_bak = False
        if os.path.exists(CONFIG_PATH):
            try:
                saved = _load_json_dict_from_file(CONFIG_PATH)
                _config_load_corrupt = False
            except Exception as e:
                print(f"Could not load saved config ({e}); checking backup...")
                corrupt_dest = f"{CONFIG_PATH}.corrupt_{int(time.time())}"
                try:
                    os.replace(CONFIG_PATH, corrupt_dest)
                    log_event(
                        "WARN",
                        f"Primary config file was corrupted and moved aside to {os.path.basename(corrupt_dest)}.",
                    )
                except Exception:
                    pass
                if os.path.exists(bak_path):
                    try:
                        saved = _load_json_dict_from_file(bak_path)
                        recovered_from_bak = True
                        _config_load_corrupt = False
                    except Exception as bak_e:
                        print(f"Could not load backup config: {bak_e}")
                        _config_load_corrupt = True
                else:
                    _config_load_corrupt = True
        elif os.path.exists(bak_path):
            try:
                saved = _load_json_dict_from_file(bak_path)
                recovered_from_bak = True
                _config_load_corrupt = False
            except Exception:
                pass

        if isinstance(saved, dict):
            try:
                was_signed = bool(saved.get("signed_tier_stops", False))
                saved_brokers = saved.pop("brokers", {})
                saved_sessions = saved.pop("account_sessions", {})
                saved_user_defs = saved.pop("user_defaults", {})
                config.update(saved)
                if str(config.get("active_broker", "")).upper() not in (
                    "SCHWAB",
                    "WEBULL",
                ):
                    config["active_broker"] = "SCHWAB"
                _last_real_broker = str(config.get("active_broker", "SCHWAB")).upper()
                for b_name in ("SCHWAB", "WEBULL"):
                    if b_name in saved_brokers and isinstance(saved_brokers[b_name], dict):
                        config["brokers"][b_name].update(saved_brokers[b_name])
                if isinstance(saved_sessions, dict):
                    config["account_sessions"].update(
                        {
                            k: v
                            for k, v in saved_sessions.items()
                            if not str(k).startswith("DEMO_")
                        }
                    )
                if isinstance(saved_user_defs, dict):
                    config["user_defaults"] = saved_user_defs
                try:
                    config["poll_interval"] = min(
                        10, max(1, int(float(config.get("poll_interval", 2))))
                    )
                except Exception:
                    config["poll_interval"] = 2
                _is_existing_user_install = bool(
                    any(
                        str(config["brokers"].get(b, {}).get("app_key", "")).strip()
                        for b in ("SCHWAB", "WEBULL")
                    )
                    or config.get("account_sessions")
                    or config.get("user_defaults")
                )

                if not was_signed:
                    for sk in SIGNED_DOLLAR_KEYS:
                        if sk in config and float(config[sk]) > 0:
                            config[sk] = -abs(float(config[sk]))
                        if (
                            isinstance(config.get("user_defaults"), dict)
                            and sk in config["user_defaults"]
                            and float(config["user_defaults"][sk]) > 0
                        ):
                            config["user_defaults"][sk] = -abs(
                                float(config["user_defaults"][sk])
                            )
                    config["signed_tier_stops"] = True
                    save_config(config)
                elif recovered_from_bak:
                    save_config(config)
                    log_event(
                        "WARN",
                        "Restored enforcer_config.json from valid .bak backup.",
                    )
            except Exception as e:
                print(f"Could not apply saved config fields: {e}")

        tester_id = str(config.get("anonymous_tester_id", "") or "").strip()
        if not tester_id:
            config["anonymous_tester_id"] = uuid.uuid4().hex[:6]
            if not _config_load_corrupt:
                save_config(config)

        today_str = get_today_str()
        c_broker = str(config.get("committed_broker", "") or "").upper()
        if c_broker == "DEMO":
            config.pop("committed_session_date", None)
            config.pop("committed_broker", None)
            config.pop("committed_account_id", None)
            committed_for_today = False
        elif str(config.get("committed_session_date", "")) == today_str:
            committed_for_today = True
            if c_broker in ("SCHWAB", "WEBULL"):
                config["active_broker"] = c_broker
                c_acct = str(config.get("committed_account_id", "") or "").strip()
                if c_acct:
                    config["brokers"][c_broker]["selected_account_id"] = c_acct
        else:
            committed_for_today = False

        active_b = config.get("active_broker", "SCHWAB")
        sel_acct = (
            config["brokers"].get(active_b, {}).get("selected_account_id", "")
        )
        if (start_equity is None or log_restore) and sel_acct:
            restore_account_session(active_b, sel_acct, log_restore=log_restore)


def save_config(new_cfg=None):
    global config, _config_load_corrupt, _last_real_broker
    with _config_io_lock:
        if new_cfg is None:
            new_cfg = config
        cfg_copy = json.loads(json.dumps(new_cfg))
        try:
            cfg_copy["poll_interval"] = min(
                10, max(1, int(float(cfg_copy.get("poll_interval", 2))))
            )
        except Exception:
            cfg_copy["poll_interval"] = 2
        cur_b = str(cfg_copy.get("active_broker", "")).upper()
        if cur_b in ("SCHWAB", "WEBULL"):
            _last_real_broker = cur_b
        if str(cfg_copy.get("committed_broker", "") or "").upper() == "DEMO":
            cfg_copy.pop("committed_session_date", None)
            cfg_copy.pop("committed_broker", None)
            cfg_copy.pop("committed_account_id", None)
        config = cfg_copy
        _config_load_corrupt = False
        try:
            disk_cfg = json.loads(json.dumps(config))
            if str(disk_cfg.get("active_broker", "")).upper() == "DEMO":
                disk_cfg["active_broker"] = (
                    _last_real_broker
                    if _last_real_broker in ("SCHWAB", "WEBULL")
                    else "SCHWAB"
                )
            if str(disk_cfg.get("committed_broker", "") or "").upper() == "DEMO":
                disk_cfg.pop("committed_session_date", None)
                disk_cfg.pop("committed_broker", None)
                disk_cfg.pop("committed_account_id", None)
            if isinstance(disk_cfg.get("account_sessions"), dict):
                disk_cfg["account_sessions"] = {
                    k: v
                    for k, v in disk_cfg["account_sessions"].items()
                    if not str(k).startswith("DEMO_")
                }
            raw_json = json.dumps(disk_cfg, indent=4)
            tmp_path = f"{CONFIG_PATH}.{threading.get_ident()}.tmp"
            bak_path = CONFIG_PATH + ".bak"
            with open(tmp_path, "w", encoding="utf-8") as f:
                f.write(raw_json)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            os.replace(tmp_path, CONFIG_PATH)
            try:
                with open(bak_path, "w", encoding="utf-8") as bf:
                    bf.write(raw_json)
            except Exception:
                pass
        except Exception as e:
            print(f"Error saving config file: {e}")


def save_session_state(
    expected_epoch=None, adapter_override=None, force_epoch_stamp=False
):
    global active_session_date
    with _config_io_lock:
        if expected_epoch is not None and expected_epoch != _adapter_epoch:
            return
        today_str = active_session_date or get_today_str()
        if active_session_date is None:
            active_session_date = today_str
        ad_ref = (
            adapter_override if adapter_override is not None else active_adapter
        )
        active_b = (
            ad_ref.name
            if ad_ref is not None
            else config.get("active_broker", "SCHWAB")
        )
        sel_acct = (
            ad_ref.account_id
            if ad_ref is not None and ad_ref.account_id
            else config.get("brokers", {}).get(active_b, {}).get("selected_account_id", "")
        )
        s_key = get_session_key(active_b, sel_acct)

        now_ep = round(time.time(), 2)
        new_entry = {
            "session_date": today_str,
            "start_equity": start_equity,
            "max_equity": max_equity,
            "daily_max_equity": daily_max_equity,
            "daily_min_equity": daily_min_equity,
            "last_flat_equity": last_flat_equity,
            "anchor_cash_flow": round(float(anchor_cash_flow or 0.0), 2),
            "has_reset_at_open": has_reset_at_open,
            "has_reset_at_close": has_reset_at_close,
            "is_locked_down": bool(is_locked_down),
            "breach_date": today_str if is_locked_down else "",
            "done_for_today": bool(done_for_today),
            "done_for_today_date": today_str if done_for_today else "",
            "committed_for_today": bool(committed_for_today),
            "committed_date": today_str if committed_for_today else "",
            "win_trades": win_trades,
            "loss_trades": loss_trades,
            "loss_timestamps": [round(float(t), 2) for t in recent_loss_timestamps],
            "ignored_positions": json.loads(json.dumps(ignored_positions)),
            "was_flat_at_save": bool(current_is_flat),
            "last_saved_epoch": now_ep,
        }

        if str(active_b).upper() == "DEMO":
            if s_key:
                _demo_memory_session[s_key] = new_entry
            return

        if "account_sessions" not in config or not isinstance(
            config["account_sessions"], dict
        ):
            config["account_sessions"] = {}

        old_entry = config["account_sessions"].get(s_key)
        old_cmp = (
            {k: v for k, v in old_entry.items() if k != "last_saved_epoch"}
            if isinstance(old_entry, dict)
            else None
        )
        new_cmp = {k: v for k, v in new_entry.items() if k != "last_saved_epoch"}
        changed = (
            force_epoch_stamp
            or old_cmp != new_cmp
            or config.get("session_date") != today_str
            or config.get("saved_start_equity") != start_equity
            or config.get("saved_max_equity") != max_equity
            or config.get("saved_daily_max_equity") != daily_max_equity
            or config.get("saved_last_flat_equity") != last_flat_equity
            or config.get("saved_has_reset_at_open") != has_reset_at_open
            or config.get("saved_has_reset_at_close") != has_reset_at_close
            or config.get("saved_win_trades") != win_trades
            or config.get("saved_loss_trades") != loss_trades
            or config.get("saved_account_id") != sel_acct
        )
        if changed:
            if s_key:
                config["account_sessions"][s_key] = new_entry
            config["session_date"] = today_str
            config["saved_start_equity"] = start_equity
            config["saved_max_equity"] = max_equity
            config["saved_daily_max_equity"] = daily_max_equity
            config["saved_last_flat_equity"] = last_flat_equity
            config["saved_has_reset_at_open"] = has_reset_at_open
            config["saved_has_reset_at_close"] = has_reset_at_close
            config["saved_win_trades"] = win_trades
            config["saved_loss_trades"] = loss_trades
            config["saved_account_id"] = sel_acct
            save_config(config)


def get_unanchored_cash_flow(intraday_cf):
    """Returns the net intraday cash deposit/transfer that has occurred SINCE
    `start_equity` was anchored today (`intraday_cf - anchor_cash_flow`).
    Subtracting this from raw liquidationValue prevents mid-session cash
    deposits from inflating Realized/Net PnL while preserving the user's
    morning baseline unless they explicitly Re-Zero Baseline."""
    global _last_logged_unanchored_cash_flow
    if (
        force_reanchor
        or start_equity is None
        or float(start_equity) <= 0.0
    ):
        return 0.0
    unanchored = round(
        float(intraday_cf or 0.0) - float(anchor_cash_flow or 0.0), 2
    )
    if abs(unanchored) < 0.01:
        _last_logged_unanchored_cash_flow = 0.0
        return 0.0
    if abs(unanchored - _last_logged_unanchored_cash_flow) >= 0.01:
        _last_logged_unanchored_cash_flow = unanchored
        cf_kind = "deposit" if unanchored >= 0.0 else "withdrawal"
        log_event(
            "SESSION",
            f"Neutralized intraday cash {cf_kind}/transfer of "
            f"{format_dollar(unanchored)} from daily PnL calculation "
            f"(Baseline=${start_equity:,.2f} preserved; use Re-Zero Baseline "
            f"if you wish to reset PnL to $0.00).",
        )
    return unanchored


_ignored_positions_lock = threading.RLock()


def _round_cents(val):
    """Two-step IEEE-754 clean cent rounding: rounds to 6 decimals first to
    eliminate ~1e-12 floating-point addition/subtraction order noise before
    rounding to cents."""
    return round(round(float(val), 6), 2)


def _has_active_open_ignored_positions(adp=None):
    """Returns True when Ticker-Level Ignore is active and at least one
    ignored position currently holds non-zero open shares/contracts."""
    with _ignored_positions_lock:
        if (
            not config.get("ignore_preexisting_positions", True)
            or not isinstance(ignored_positions, dict)
            or not ignored_positions
            or is_demo_mode_active(adp if adp is not None else active_adapter)
        ):
            return False
        for ig in ignored_positions.values():
            if isinstance(ig, dict) and abs(float(ig.get("ref_qty", 0.0))) > 1e-6:
                return True
        return False


def is_position_ignored(sym_or_tag, is_opt=False):
    """Returns True if sym_or_tag is currently registered in ignored_positions
    and 'ignore_preexisting_positions' is enabled in config."""
    with _ignored_positions_lock:
        if (
            not config.get("ignore_preexisting_positions", True)
            or not ignored_positions
            or is_demo_mode_active()
        ):
            return False
        s = str(sym_or_tag or "").strip()
        if not s:
            return False
        tag = f"{s} (OPT)" if (is_opt and not s.endswith(" (OPT)")) else s
        if tag in ignored_positions:
            return True
        if not isinstance(ignored_positions, dict):
            return False
        base_s = s[:-6].strip() if s.endswith(" (OPT)") else s
        for ig_tag, ig in ignored_positions.items():
            if not isinstance(ig, dict):
                continue
            ig_is_opt = (ig.get("asset_type") == "OPTION") or ig_tag.endswith(" (OPT)")
            if bool(is_opt) != bool(ig_is_opt):
                continue
            if (
                str(ig.get("symbol", "")).strip() == base_s
                or str(ig.get("raw_symbol", "")).strip() == base_s
            ):
                return True
        return False


def build_ignored_position_entry(tag, d, lock_existing_open_pnl=False):
    """Builds a fresh ignored_positions entry from a raw position dict d.
    If lock_existing_open_pnl is True (e.g. a new position opened mid-day while
    Enforcer was closed and marked Ignored on re-launch without re-zeroing
    start_equity), initializes locked_impact to d['open_pnl'] so its unrealized
    gain/loss since purchase is neutralized relative to the morning baseline."""
    qty = float(d.get("qty", 0.0))
    lp = float(d.get("last", 0.0))
    avg = float(d.get("avg", 0.0))
    opnl = round(float(d.get("open_pnl", 0.0)), 2)
    a_type = str(d.get("asset_type", "EQUITY")).upper()
    base_sym = tag[:-6].strip() if str(tag).endswith(" (OPT)") else str(tag)
    init_locked = opnl if lock_existing_open_pnl else 0.0
    return {
        "symbol": str(d.get("symbol") or base_sym),
        "raw_symbol": str(d.get("raw_symbol") or base_sym),
        "asset_type": a_type,
        "init_qty": qty,
        "init_price": round(lp, 4),
        "ref_qty": qty,
        "ref_price": round(lp, 4),
        "ref_avg": round(avg, 4),
        "ref_open_pnl": opnl,
        "last_seen_price": round(lp, 4),
        "locked_impact": init_locked,
    }


def reanchor_ignored_positions_to_live(raw_pos_details=None):
    """Re-anchors all currently tracked ignored_positions entries to their
    current live price with locked_impact = 0.0 when start_equity is freshly
    anchored or re-zeroed."""
    with _ignored_positions_lock:
        if not ignored_positions or not isinstance(ignored_positions, dict):
            return
    if not isinstance(raw_pos_details, dict):
        adp = (
            raw_pos_details
            if (
                hasattr(raw_pos_details, "get_last_raw_pos_details")
                or hasattr(raw_pos_details, "get_last_raw_positions_snapshot")
            )
            else active_adapter
        )
        if adp is not None and hasattr(adp, "get_last_raw_pos_details"):
            raw_pos_details = adp.get_last_raw_pos_details()
        elif adp is not None and hasattr(adp, "get_last_raw_positions_snapshot"):
            snap_res = adp.get_last_raw_positions_snapshot()
            raw_pos_details = (
                snap_res[0]
                if isinstance(snap_res, tuple) and len(snap_res) > 0
                else snap_res
            )
        elif adp is not None and hasattr(adp, "_last_raw_pos_details"):
            raw_pos_details = (
                getattr(adp, "_last_raw_pos_details", {}).get(
                    getattr(adp, "account_id", ""), {}
                )
            )
    if not isinstance(raw_pos_details, dict):
        return
    with _ignored_positions_lock:
        if not isinstance(ignored_positions, dict):
            return
        for tag, ig in list(ignored_positions.items()):
            if not isinstance(ig, dict):
                continue
            d = raw_pos_details.get(tag)
            if d is not None:
                qty = float(d.get("qty", 0.0))
                lp = float(d.get("last", 0.0))
                avg = float(d.get("avg", 0.0))
                opnl = round(float(d.get("open_pnl", 0.0)), 2)
                ig["init_qty"] = qty
                ig["init_price"] = round(lp, 4)
                ig["ref_qty"] = qty
                ig["ref_price"] = round(lp, 4)
                ig["ref_avg"] = round(avg, 4)
                ig["ref_open_pnl"] = opnl
                ig["last_seen_price"] = round(lp, 4)
                ig["locked_impact"] = 0.0
            else:
                ig["ref_qty"] = 0.0
                ig["ref_open_pnl"] = 0.0
                ig["locked_impact"] = 0.0


def _apply_ignored_positions_to_snapshot(
    raw_adj_eq, raw_pos_details, open_eq_cache, open_opt_cache
):
    """Filters out any ignored pre-existing positions (Ticker-Level Ignore) from
    pos_details, open_pnl, has_options, and flatten caches, and neutralizes
    their intraday PnL impact (across price moves, adds, partial sells, and
    full closes) from raw_adj_eq."""
    global _cold_launch_ignored_qty_mutated
    if not isinstance(raw_pos_details, dict):
        raw_pos_details = {}
    with _ignored_positions_lock:
        if (
            not config.get("ignore_preexisting_positions", True)
            or not ignored_positions
            or not isinstance(ignored_positions, dict)
            or is_demo_mode_active()
        ):
            tot_open = round(
                sum(float(d.get("open_pnl", 0.0)) for d in raw_pos_details.values()),
                2,
            )
            has_opt = any(
                d.get("asset_type") == "OPTION" for d in raw_pos_details.values()
            )
            return (
                _round_cents(raw_adj_eq) if raw_adj_eq is not None else None,
                (len(raw_pos_details) == 0),
                tot_open,
                dict(raw_pos_details),
                has_opt,
                list(open_eq_cache or []),
                list(open_opt_cache or []),
            )

        filt_pos_details = {
            k: v
            for k, v in raw_pos_details.items()
            if not is_position_ignored(k, v.get("asset_type") == "OPTION")
        }
        filt_eq_cache = [
            item
            for item in (open_eq_cache or [])
            if not is_position_ignored(item[0], is_opt=False)
        ]
        filt_opt_cache = [
            item
            for item in (open_opt_cache or [])
            if not is_position_ignored(item[0], is_opt=True)
        ]
        tot_open_pnl = round(
            sum(float(d.get("open_pnl", 0.0)) for d in filt_pos_details.values()),
            2,
        )
        has_options = any(
            d.get("asset_type") == "OPTION" for d in filt_pos_details.values()
        )
        is_flat = (len(filt_pos_details) == 0)

        sum_ignored_impact = 0.0
        state_mutated = False
        mutated_igs = []
        mutated_notional = 0.0
        transition_notes = []

        for tag, ig in list(ignored_positions.items()):
            if not isinstance(ig, dict):
                continue
            d = raw_pos_details.get(tag)
            if d is None:
                base_s = str(ig.get("symbol", "")).strip()
                for cand_tag, cand_d in raw_pos_details.items():
                    cand_base = (
                        cand_tag[:-6].strip()
                        if str(cand_tag).endswith(" (OPT)")
                        else str(cand_tag)
                    )
                    if cand_base == base_s and (
                        cand_d.get("asset_type") == ig.get("asset_type")
                    ):
                        d = cand_d
                        break

            a_type = str(
                (d or {}).get("asset_type") or ig.get("asset_type") or "EQUITY"
            ).upper()
            mult = 100.0 if a_type == "OPTION" else 1.0
            ref_qty = float(ig.get("ref_qty", 0.0))
            ref_price = float(ig.get("ref_price", 0.0))
            ref_avg = float(ig.get("ref_avg", 0.0))
            ref_open_pnl = ig.get("ref_open_pnl")
            last_seen_lp = float(ig.get("last_seen_price") or ref_price)
            locked_impact = float(ig.get("locked_impact", 0.0))

            if d is None or float(d.get("qty", 0.0)) == 0.0:
                # Position is currently closed (0 shares/contracts)
                if abs(ref_qty) > 1e-6:
                    exit_lp = last_seen_lp if last_seen_lp > 0 else ref_price
                    locked_impact = _round_cents(
                        locked_impact + ref_qty * (exit_lp - ref_price) * mult
                    )
                    transition_notes.append(
                        f"{tag}: {ref_qty:+g} -> 0 (Ignored position closed @ ~${exit_lp:.4f})"
                    )
                    mutated_notional += abs(ref_qty) * max(exit_lp, ref_price, 1.0) * mult
                    ig["ref_qty"] = 0.0
                    ig["ref_price"] = round(exit_lp, 4)
                    ig["ref_avg"] = 0.0
                    ig["ref_open_pnl"] = 0.0
                    ig["locked_impact"] = locked_impact
                    state_mutated = True
                    mutated_igs.append(ig)
                sum_ignored_impact += locked_impact
                continue

            curr_qty = float(d.get("qty", 0.0))
            curr_lp = float(d.get("last", 0.0))
            curr_avg = float(d.get("avg", 0.0))
            curr_open_pnl = float(d.get("open_pnl", 0.0))

            if abs(curr_qty - ref_qty) > 1e-6:
                # Ignored position quantity changed (added, trimmed, re-opened, or flipped)
                if abs(ref_qty) < 1e-6:
                    # Re-opened from 0 on an ignored ticker
                    locked_impact = _round_cents(locked_impact + curr_open_pnl)
                elif (curr_qty * ref_qty) > 0 and abs(curr_qty) > abs(ref_qty):
                    # Added to ignored position in same direction (0 shares closed,
                    # so exact equity delta since ref is curr_open_pnl - ref_open_pnl)
                    if ref_open_pnl is not None:
                        locked_impact = _round_cents(
                            locked_impact + (curr_open_pnl - float(ref_open_pnl))
                        )
                    else:
                        added_q = curr_qty - ref_qty
                        old_delta = ref_qty * (curr_lp - ref_price) * mult
                        new_delta = 0.0
                        if curr_avg > 0 and ref_avg > 0 and abs(added_q) > 1e-6:
                            inferred_fill = (
                                (abs(curr_qty) * curr_avg) - (abs(ref_qty) * ref_avg)
                            ) / abs(added_q)
                            if (
                                curr_lp > 0
                                and (0.5 * curr_lp) <= inferred_fill <= (1.5 * curr_lp)
                            ):
                                new_delta = added_q * (curr_lp - inferred_fill) * mult
                        locked_impact = _round_cents(locked_impact + old_delta + new_delta)
                elif (curr_qty * ref_qty) > 0 and abs(curr_qty) < abs(ref_qty):
                    # Trimmed / partially sold ignored position
                    locked_impact = _round_cents(
                        locked_impact + ref_qty * (curr_lp - ref_price) * mult
                    )
                else:
                    # Flipped sign on ignored ticker
                    locked_impact = _round_cents(
                        locked_impact
                        + ref_qty * (curr_lp - ref_price) * mult
                        + curr_open_pnl
                    )
                transition_notes.append(
                    f"{tag}: {ref_qty:+g} -> {curr_qty:+g} (Ignored ticker)"
                )
                mutated_notional += (
                    abs(curr_qty - ref_qty)
                    * max(curr_lp, ref_price, 1.0)
                    * mult
                )
                ig["ref_qty"] = curr_qty
                ig["ref_price"] = round(curr_lp, 4)
                ig["ref_avg"] = round(curr_avg, 4)
                ig["ref_open_pnl"] = round(curr_open_pnl, 2)
                ig["last_seen_price"] = round(curr_lp, 4)
                ig["locked_impact"] = locked_impact
                state_mutated = True
                mutated_igs.append(ig)
                sum_ignored_impact += locked_impact
            else:
                ig["last_seen_price"] = round(curr_lp, 4)
                open_impact = curr_qty * (curr_lp - ref_price) * mult
                sum_ignored_impact += locked_impact + open_impact

        if state_mutated:
            if first_poll_of_launch:
                _cold_launch_ignored_qty_mutated = True
            if mutated_igs and raw_adj_eq is not None:
                tracked_qty_changed = (
                    set(filt_pos_details.keys()) != set(prev_pos_snapshot.keys())
                    or any(
                        abs(
                            float(filt_pos_details[k].get("qty", 0.0))
                            - float(prev_pos_snapshot[k].get("qty", 0.0))
                        )
                        > 1e-6
                        for k in filt_pos_details
                    )
                )
                ref_flat_eq = (
                    last_flat_equity if last_flat_equity is not None else start_equity
                )
                if (
                    not first_poll_of_launch
                    and not tracked_qty_changed
                    and ref_flat_eq is not None
                    and float(ref_flat_eq) > 0.0
                ):
                    target_sum_ignored = _round_cents(
                        (float(raw_adj_eq) - tot_open_pnl) - float(ref_flat_eq)
                    )
                    drift = _round_cents(target_sum_ignored - sum_ignored_impact)
                    max_drift_cap = min(5000.0, max(250.0, mutated_notional * 0.05))
                    if abs(drift) >= 0.01:
                        if abs(drift) <= max_drift_cap:
                            last_ig = mutated_igs[-1]
                            last_ig["locked_impact"] = _round_cents(
                                float(last_ig.get("locked_impact", 0.0)) + drift
                            )
                            sum_ignored_impact = _round_cents(sum_ignored_impact + drift)
                        else:
                            log_event(
                                "WARN",
                                f"Ignored position fill drift ({format_dollar(drift)}) exceeded "
                                f"proportional cap (${max_drift_cap:,.2f}); not absorbing excess drift.",
                            )
            save_session_state()
            if transition_notes:
                log_event(
                    "SESSION",
                    f"Ignored pre-existing position activity neutralized: "
                    f"{', '.join(transition_notes)}",
                )

        adj_eq = (
            _round_cents(float(raw_adj_eq) - sum_ignored_impact)
            if raw_adj_eq is not None
            else None
        )
        return (
            adj_eq,
            is_flat,
            tot_open_pnl,
            filt_pos_details,
            has_options,
            filt_eq_cache,
            filt_opt_cache,
        )


