def is_nyse_early_close_day(now_et=None):
    dt_et = now_et if now_et is not None else get_eastern_now()
    return dt_et.strftime("%Y-%m-%d") in NYSE_EARLY_CLOSE_DATES


def get_rth_close_time(now_et=None):
    global _calendar_table_warned
    dt_et = now_et if now_et is not None else get_eastern_now()
    if dt_et.year > 2028 and not _calendar_table_warned:
        _calendar_table_warned = True
        try:
            log_event(
                "WARN",
                f"NYSE early-close calendar table ends in 2028 (current year: {dt_et.year}); "
                f"defaulting RTH close to 4:00 PM ET.",
            )
        except Exception:
            pass
    if is_nyse_early_close_day(dt_et):
        return dt_time(13, 0)
    return dt_time(16, 0)


def is_rth():
    now_et = get_eastern_now()
    return dt_time(9, 30) <= now_et.time() < get_rth_close_time(now_et)


def is_after_hours():
    now_et = get_eastern_now()
    return now_et.time() >= get_rth_close_time(now_et)


def is_market_hours():
    now_et = get_eastern_now()
    return dt_time(9, 30) <= now_et.time() < get_rth_close_time(now_et)


def is_any_equity_session_open(broker_name=None):
    """Returns True when either Regular Trading Hours or the broker's Extended
    Hours equity session is open (weekdays not in NYSE_FULL_HOLIDAY_DATES;
    7:00 AM–8:00 PM ET for Schwab, 4:00 AM–8:00 PM ET for Webull, closing at
    5:00 PM ET on NYSE early-close dates)."""
    now_et = get_eastern_now()
    if now_et.weekday() >= 5:
        return False
    d_str = now_et.strftime("%Y-%m-%d")
    if d_str in NYSE_FULL_HOLIDAY_DATES:
        return False
    b_up = str(
        broker_name
        or (active_adapter.name if active_adapter is not None else "")
        or config.get("active_broker", "SCHWAB")
    ).upper()
    open_t = dt_time(4, 0) if "WEBULL" in b_up else dt_time(7, 0)
    close_t = (
        dt_time(17, 0) if d_str in NYSE_EARLY_CLOSE_DATES else dt_time(20, 0)
    )
    return open_t <= now_et.time() < close_t


def calc_ext_limit_price(ref_price, is_sell=True):
    """Calculates a marketable extended-hours limit price just past
    the current Bid/Ask without triggering broker price-collar rejections."""
    if ref_price < 1.0:
        offset = min(max(ref_price * 0.02, 0.005), 0.02)
        raw = (ref_price - offset) if is_sell else (ref_price + offset)
        return round(max(0.0001, raw), 4)
    elif ref_price < 3.0:
        offset = 0.03
    elif ref_price < 10.0:
        offset = 0.05
    else:
        offset = min(ref_price * 0.01, 0.15)

    offset = min(offset, ref_price * 0.025)
    raw = (ref_price - offset) if is_sell else (ref_price + offset)
    return round(max(0.01, raw), 2)


def format_limit_price_str(price_val):
    """Formats a limit price float as a clean string (2 decimals for >= $1.00,
    up to 4 decimals for sub-$1.00 stocks) so schwab-py and Webull SDKs
    never emit float deprecation warnings or float precision artifacts."""
    p = float(price_val)
    if p < 1.0:
        s = f"{p:.4f}".rstrip("0").rstrip(".")
        if "." not in s:
            return f"{p:.2f}"
        dec_part = s.split(".")[1]
        if len(dec_part) < 2:
            return f"{p:.2f}"
        return s
    return f"{p:.2f}"


def sanitize_equity_live_price(raw_last, bid=None, ask=None, mark=None, net_qty=0):
    """Protects equity open PnL valuation against off-exchange FINRA TRF / dark-pool
    sub-penny prints and single-order wicks that fall outside the live NBBO
    [bid, ask] spread."""
    def _pos_f(v):
        try:
            f = float(v)
            return f if f > 0.0 else None
        except Exception:
            return None

    lp = _pos_f(raw_last)
    b = _pos_f(bid)
    a = _pos_f(ask)
    m = _pos_f(mark)

    if lp is None:
        lp = m or b or a
    if lp is None:
        return None

    if b is not None and a is not None and b <= a:
        if lp < b:
            return b
        if lp > a:
            return a
        return lp

    if net_qty > 0 and b is not None and lp < b:
        return b
    if net_qty < 0 and a is not None and lp > a:
        return a

    return lp


def compute_book_confirmed_price(
    lp, bid=None, ask=None, mark=None, acct_lp=None, net_qty=0
):
    """Computes the book-confirmed reference price across the live NBBO midpoint
    (or mark) and the broker's position snapshot price so real market moves fire
    immediately (0s delay) while single-order wicks or entry-sweep quote lags
    are caught and verified."""
    def _pos_f(v):
        try:
            f = float(v)
            return f if f > 0.0 else None
        except Exception:
            return None

    b = _pos_f(bid)
    a = _pos_f(ask)
    m = _pos_f(mark)
    ac = _pos_f(acct_lp)

    if b is not None and a is not None and b <= a:
        mid_p = round((b + a) / 2.0, 4)
    elif m is not None:
        mid_p = m
    else:
        mid_p = lp

    cands = [lp, mid_p]
    if ac is not None:
        cands.append(ac)
    if net_qty > 0:
        return max(cands)
    if net_qty < 0:
        return min(cands)
    return lp


