    def _cancel_pf_timers():
        pf_timer_state["closing"] = True
        try:
            pf._pf_stop_pulse_fn = None
            pf.unbind("<Button-1>")
        except Exception:
            pass
        for k_id in ("rulebook_after_id", "streak_after_id", "pulse_after_id"):
            aid = pf_timer_state.get(k_id)
            if aid is not None:
                pf_timer_state[k_id] = None
                try:
                    pf.after_cancel(aid)
                except Exception:
                    pass
        cleanup_fn = _prefs_modal_refs.get("cleanup_fn")
        if callable(cleanup_fn):
            try:
                cleanup_fn()
            except Exception:
                pass

