def _is_beta_channel_build():
    """Returns True when running from the experimental 'beta' git branch or a
    Beta Channel Gist bundle (28088fe94e866e249b2c794c25eef6e9), so web
    changelog links, remote doc fetches, and update checks automatically use
    the Beta Channel without manual URL switching on branch merges."""
    try:
        git_head_path = os.path.join(SCRIPT_DIR, ".git", "HEAD")
        if os.path.exists(git_head_path):
            with open(
                git_head_path, "r", encoding="utf-8", errors="replace"
            ) as hf:
                if "refs/heads/beta" in hf.read():
                    return True
    except Exception:
        pass
    try:
        bat_path = os.path.join(SCRIPT_DIR, "Launch_Enforcer.bat")
        if os.path.exists(bat_path):
            with open(
                bat_path, "r", encoding="utf-8", errors="replace"
            ) as bf:
                if BETA_GIST_BUNDLE_ID in bf.read():
                    return True
    except Exception:
        pass
    return False


def get_changelog_web_url():
    """Returns the Beta Channel Gist Changelog URL when running on the beta
    branch/channel, or the Main Stable Changelog Gist URL on stable builds."""
    return (
        BETA_CHANGELOG_WEB_URL
        if _is_beta_channel_build()
        else CHANGELOG_WEB_URL
    )


def get_source_diff_web_url():
    """Returns the GitHub Gist '/revisions' source-diff URL for the active
    channel so security-conscious users can inspect full source code and
    line-by-line version diffs in their browser before or after updating."""
    return (
        BETA_SOURCE_DIFF_WEB_URL
        if _is_beta_channel_build()
        else SOURCE_DIFF_WEB_URL
    )


def _parse_version_tuple(v_str):
    nums = [int(x) for x in re.findall(r"\d+", str(v_str))]
    return tuple(nums) if nums else (0,)


def _fetch_remote_doc_bytes(doc_name, ts=None):
    import urllib.request
    if ts is None:
        ts = int(time.time())
    is_beta = _is_beta_channel_build()
    if is_beta:
        doc_urls = [
            f"https://gist.githubusercontent.com/DBCodez/{BETA_GIST_BUNDLE_ID}/raw/{doc_name}?t={ts}",
            f"{BETA_GITHUB_RAW_BASE}{doc_name}?t={ts}",
        ]
    else:
        doc_urls = [f"{GITHUB_RAW_BASE}{doc_name}?t={ts}"]
        if doc_name in GIST_DOC_RAW_URLS:
            doc_urls.append(f"{GIST_DOC_RAW_URLS[doc_name]}?t={ts}")
    for d_url in doc_urls:
        try:
            d_req = urllib.request.Request(
                d_url,
                headers={
                    "User-Agent": f"PnL-Enforcer-Updater/{APP_VERSION}",
                    "Cache-Control": "no-cache",
                },
            )
            with urllib.request.urlopen(d_req, timeout=3) as d_resp:
                doc_bytes = d_resp.read()
            if doc_bytes:
                if is_beta and doc_name == "Launch_Enforcer.bat":
                    doc_bytes = (
                        doc_bytes.decode("utf-8", errors="replace")
                        .replace(MAIN_GIST_BUNDLE_ID, BETA_GIST_BUNDLE_ID)
                        .encode("utf-8")
                    )
                return doc_bytes
        except Exception:
            continue
    return None


def _insert_formatted_changelog(txt_box, markdown_text):
    """Renders Markdown release notes into a tk.Text widget with rich typography,
    comfortable line spacing, highlighted Quick Summary blocks, clickable
    collapsible version headers & Detailed Breakdown sections, and version marks."""
    body_fam = "Arial"
    bold_fam = "Arial"
    txt_box.config(
        font=(body_fam, 10, "bold"),
        fg="#dce4ee",
        bg="#151d28",
        padx=18,
        pady=14,
    )
    txt_box.tag_configure(
        "doc_title",
        font=(bold_fam, 13, "bold"),
        foreground="#ffffff",
        spacing1=2,
        spacing3=4,
    )
    txt_box.tag_configure(
        "doc_sub",
        font=(body_fam, 10, "bold"),
        foreground="#94a3b8",
        spacing1=0,
        spacing3=10,
    )
    import tkinter.font as tkfont

    ver_tab_px = 340
    try:
        _ver_font = tkfont.Font(font=(bold_fam, 11, "bold"))
        _base_tab_px = _ver_font.measure("  ▼  v0.9.56 — 2026-11-14" + (" " * 42))
        _longest_hdr_px = 0
        for _hdr_ln in str(markdown_text or "").splitlines():
            _hdr_st = _hdr_ln.strip()
            if _hdr_st.startswith("## "):
                _hdr_clean = _hdr_st[3:].strip().replace("[", "").replace("]", "")
                _longest_hdr_px = max(
                    _longest_hdr_px, _ver_font.measure(f"  ▼  {_hdr_clean}") + 28
                )
        ver_tab_px = max(340, int(_base_tab_px), int(_longest_hdr_px))
    except Exception:
        ver_tab_px = 340

    txt_box.tag_configure(
        "ver_hdr",
        font=(bold_fam, 11, "bold"),
        foreground="#00e676",
        background="#142e24",
        tabs=(ver_tab_px,),
        spacing1=12,
        spacing3=8,
    )
    txt_box.tag_configure(
        "ver_hdr_hint",
        font=(bold_fam, 9, "bold"),
        foreground="#6ee7b7",
        background="#142e24",
    )
    txt_box.tag_configure(
        "qsum_hdr",
        font=(bold_fam, 10, "bold"),
        foreground="#fbbf24",
        spacing1=8,
        spacing3=4,
    )
    txt_box.tag_configure(
        "qsum_bullet",
        font=(body_fam, 10, "bold"),
        foreground="#dce4ee",
        lmargin1=12,
        lmargin2=28,
        rmargin=12,
        spacing1=6,
        spacing2=5,
        spacing3=6,
    )
    txt_box.tag_configure(
        "qsum_marker",
        font=(bold_fam, 10, "bold"),
        foreground="#34d399",
    )
    txt_box.tag_configure(
        "sec_hdr",
        font=(bold_fam, 10, "bold"),
        foreground="#38bdf8",
        spacing1=12,
        spacing3=6,
    )
    txt_box.tag_configure(
        "sec_hdr_hint",
        font=(bold_fam, 9, "bold"),
        foreground="#94a3b8",
    )
    txt_box.tag_configure(
        "bullet_1",
        font=(body_fam, 10, "bold"),
        foreground="#dce4ee",
        lmargin1=12,
        lmargin2=28,
        rmargin=12,
        spacing1=8,
        spacing2=5,
        spacing3=5,
    )
    txt_box.tag_configure(
        "bullet_2",
        font=(body_fam, 10, "bold"),
        foreground="#cbd5e1",
        lmargin1=30,
        lmargin2=46,
        rmargin=12,
        spacing1=4,
        spacing2=5,
        spacing3=5,
    )
    txt_box.tag_configure(
        "body_line",
        font=(body_fam, 10, "bold"),
        foreground="#dce4ee",
        spacing1=4,
        spacing2=5,
        spacing3=5,
    )
    txt_box.tag_configure(
        "bold_lead",
        font=(bold_fam, 10, "bold"),
        foreground="#ffd166",
    )
    txt_box.tag_configure(
        "sub_bold_lead",
        font=(bold_fam, 10, "bold"),
        foreground="#7dd3fc",
    )
    txt_box.tag_configure(
        "bold_inline",
        font=(bold_fam, 10, "bold"),
        foreground="#ffffff",
    )
    txt_box.tag_configure(
        "code_span",
        font=(bold_fam, 10, "bold"),
        foreground="#67e8f9",
    )
    txt_box.tag_configure(
        "italic_span",
        font=(body_fam, 10, "bold"),
        foreground="#a3e4d7",
    )
    txt_box.tag_configure(
        "hr_div",
        font=(bold_fam, 8),
        foreground="#263548",
        spacing1=10,
        spacing3=8,
    )

    versions = []
    curr_ver_idx = None
    in_quick_summary = False
    in_detailed_breakdown = False

    _EMOJI_STRIP_RE = re.compile(
        r"[\U0001F300-\U0001FAFF\u2699\uFE0F\u2728\u2705]+"
    )

    def _clean_tk_text(s):
        cleaned = _EMOJI_STRIP_RE.sub("", str(s or ""))
        cleaned = re.sub(r"\(\s*,\s*", "(", cleaned)
        cleaned = re.sub(r"\(\s+", "(", cleaned)
        cleaned = re.sub(r"\s+\)", ")", cleaned)
        cleaned = re.sub(r"\(\s*\)", "", cleaned)
        return re.sub(r"  +", " ", cleaned)

    def _active_scope_tags():
        tags = []
        if curr_ver_idx is not None:
            tags.append(f"ver_body_{curr_ver_idx}")
            if in_detailed_breakdown:
                tags.append(f"det_body_{curr_ver_idx}")
        return tuple(tags)

    def _insert_rich_spans(text_line, base_tag):
        scope_tags = _active_scope_tags()
        text_line = _clean_tk_text(text_line).strip()
        parts = re.split(r"(\*\*.*?\*\*|`[^`]+`|\*\"[^\"]+\"\*)", text_line)
        first_bold_seen = False
        lead_tag = "sub_bold_lead" if base_tag == "bullet_2" else "bold_lead"
        for part in parts:
            if not part:
                continue
            if part.startswith("**") and part.endswith("**") and len(part) > 4:
                inner = _clean_tk_text(part[2:-2].replace("`", "")).strip()
                if not inner:
                    continue
                b_tag = lead_tag if not first_bold_seen else "bold_inline"
                first_bold_seen = True
                txt_box.insert("end", inner, (base_tag, b_tag) + scope_tags)
            elif part.startswith("`") and part.endswith("`") and len(part) > 2:
                inner_code = _clean_tk_text(part[1:-1]).strip()
                if not inner_code:
                    continue
                txt_box.insert("end", inner_code, (base_tag, "code_span") + scope_tags)
            elif part.startswith('*"') and part.endswith('"*') and len(part) > 4:
                txt_box.insert("end", part[1:-1], (base_tag, "italic_span") + scope_tags)
            else:
                cleaned_part = _clean_tk_text(part)
                if cleaned_part:
                    txt_box.insert("end", cleaned_part, (base_tag,) + scope_tags)
        txt_box.insert("end", "\n", (base_tag,) + scope_tags)

    def _format_ver_hdr_line(ver_label, collapsed):
        arrow = "▶" if collapsed else "▼"
        hint = "[Click to Expand]" if collapsed else "[Click to Collapse]"
        return f"  {arrow}  {ver_label}\t", f"{hint}  \n"

    def _format_det_hdr_line(sec_title, collapsed):
        arrow = "▸" if collapsed else "▼"
        hint = "  [Click to Show Details]" if collapsed else "  [Click to Hide Details]"
        return f"{arrow} {sec_title}", f"{hint}\n"

    for raw_ln in str(markdown_text or "").splitlines():
        stripped = raw_ln.strip()
        if not stripped:
            continue
        if stripped.startswith("# "):
            in_quick_summary = False
            in_detailed_breakdown = False
            txt_box.insert(
                "end",
                stripped[2:].strip() + "\n",
                ("doc_title",) + _active_scope_tags(),
            )
        elif stripped.startswith("## "):
            in_quick_summary = False
            in_detailed_breakdown = False
            ver_txt = stripped[3:].strip().replace("[", "").replace("]", "")
            v_idx = len(versions)
            curr_ver_idx = v_idx
            mark_name = f"ver_mark_{v_idx}"
            hdr_tag = f"ver_hdr_{v_idx}"
            body_tag = f"ver_body_{v_idx}"
            det_tag = f"det_body_{v_idx}"
            txt_box.mark_set(mark_name, "end-1c")
            txt_box.mark_gravity(mark_name, "left")
            main_part, hint_part = _format_ver_hdr_line(ver_txt, False)
            txt_box.insert("end", main_part, ("ver_hdr", hdr_tag))
            txt_box.insert("end", hint_part, ("ver_hdr", "ver_hdr_hint", hdr_tag))
            short_m = re.match(
                r"^(v?\d+\.\d+(?:\.\d+)*(?:\s*(?:[&,–-]\s*v?\d+\.\d+(?:\.\d+)*)+)?)",
                ver_txt,
            )
            short_ver = short_m.group(1) if short_m else ver_txt[:12]
            versions.append({
                "idx": v_idx,
                "label": ver_txt,
                "short": short_ver,
                "mark": mark_name,
                "hdr_tag": hdr_tag,
                "body_tag": body_tag,
                "det_hdr_tag": f"det_hdr_{v_idx}",
                "det_tag": det_tag,
                "det_title": "DETAILED BREAKDOWN",
                "collapsed": False,
                "details_collapsed": False,
            })
        elif stripped.startswith("### "):
            sec_raw = stripped[4:].strip()
            sec_upper = sec_raw.upper()
            if "SUMMARY" in sec_upper or "HIGHLIGHT" in sec_upper:
                in_quick_summary = True
                in_detailed_breakdown = False
                scope_t = (f"ver_body_{curr_ver_idx}",) if curr_ver_idx is not None else ()
                txt_box.insert(
                    "end",
                    f"⚡ {_clean_tk_text(sec_upper.lstrip('⚡'))}\n",
                    ("qsum_hdr",) + scope_t,
                )
            else:
                in_quick_summary = False
                in_detailed_breakdown = True
                clean_title = _clean_tk_text(sec_upper)
                if curr_ver_idx is not None:
                    v_info = versions[curr_ver_idx]
                    v_info["det_title"] = clean_title
                    d_hdr_tag = v_info["det_hdr_tag"]
                    scope_t = (v_info["body_tag"],)
                    m_part, h_part = _format_det_hdr_line(clean_title, False)
                    txt_box.insert("end", m_part, ("sec_hdr", d_hdr_tag) + scope_t)
                    txt_box.insert("end", h_part, ("sec_hdr", "sec_hdr_hint", d_hdr_tag) + scope_t)
                else:
                    txt_box.insert("end", f"▸ {clean_title}\n", ("sec_hdr",))
        elif stripped.startswith("---"):
            in_quick_summary = False
            in_detailed_breakdown = False
            scope_t = (f"ver_body_{curr_ver_idx}",) if curr_ver_idx is not None else ()
            txt_box.insert("end", "─" * 102 + "\n", ("hr_div",) + scope_t)
        elif raw_ln.startswith("  - ") or raw_ln.startswith("    - "):
            txt_box.insert("end", "◦  ", ("bullet_2", "bold_inline") + _active_scope_tags())
            _insert_rich_spans(stripped[2:].strip(), "bullet_2")
        elif stripped.startswith("- "):
            if in_quick_summary:
                txt_box.insert("end", "✦  ", ("qsum_bullet", "qsum_marker") + _active_scope_tags())
                _insert_rich_spans(stripped[2:].strip(), "qsum_bullet")
            else:
                txt_box.insert("end", "•  ", ("bullet_1", "bold_lead") + _active_scope_tags())
                _insert_rich_spans(stripped[2:].strip(), "bullet_1")
        elif stripped.startswith("All notable updates"):
            txt_box.insert("end", stripped + "\n", ("doc_sub",))
        else:
            _insert_rich_spans(stripped, "body_line")

    def _set_version_collapsed(v_idx, collapsed_state):
        if v_idx < 0 or v_idx >= len(versions):
            return
        v_info = versions[v_idx]
        v_info["collapsed"] = bool(collapsed_state)
        hdr_tag = v_info["hdr_tag"]
        ranges = txt_box.tag_ranges(hdr_tag)
        if len(ranges) >= 2:
            prev_state = str(txt_box.cget("state"))
            txt_box.config(state="normal")
            start_pos = ranges[0]
            end_pos = ranges[-1]
            txt_box.delete(start_pos, end_pos)
            m_part, h_part = _format_ver_hdr_line(v_info["label"], v_info["collapsed"])
            txt_box.insert(start_pos, m_part, ("ver_hdr", hdr_tag))
            txt_box.insert(
                f"{start_pos} + {len(m_part)}c",
                h_part,
                ("ver_hdr", "ver_hdr_hint", hdr_tag),
            )
            txt_box.config(state=prev_state)
        txt_box.tag_configure(v_info["body_tag"], elide=bool(v_info["collapsed"]))
        if v_info["collapsed"]:
            txt_box.tag_configure(v_info["det_tag"], elide=True)
        else:
            txt_box.tag_configure(
                v_info["det_tag"], elide=bool(v_info["details_collapsed"])
            )

    def _set_details_collapsed(v_idx, det_collapsed_state):
        if v_idx < 0 or v_idx >= len(versions):
            return
        v_info = versions[v_idx]
        v_info["details_collapsed"] = bool(det_collapsed_state)
        d_hdr_tag = v_info["det_hdr_tag"]
        ranges = txt_box.tag_ranges(d_hdr_tag)
        if len(ranges) >= 2:
            prev_state = str(txt_box.cget("state"))
            txt_box.config(state="normal")
            start_pos = ranges[0]
            end_pos = ranges[-1]
            txt_box.delete(start_pos, end_pos)
            m_part, h_part = _format_det_hdr_line(
                v_info["det_title"], v_info["details_collapsed"]
            )
            scope_t = (v_info["body_tag"],)
            txt_box.insert(start_pos, m_part, ("sec_hdr", d_hdr_tag) + scope_t)
            txt_box.insert(
                f"{start_pos} + {len(m_part)}c",
                h_part,
                ("sec_hdr", "sec_hdr_hint", d_hdr_tag) + scope_t,
            )
            txt_box.config(state=prev_state)
        if not v_info["collapsed"]:
            txt_box.tag_configure(
                v_info["det_tag"], elide=bool(v_info["details_collapsed"])
            )

    for v_info in versions:
        idx_val = v_info["idx"]
        h_tag = v_info["hdr_tag"]
        d_tag = v_info["det_hdr_tag"]
        txt_box.tag_bind(
            h_tag,
            "<Button-1>",
            lambda _e, i=idx_val: _set_version_collapsed(
                i, not versions[i]["collapsed"]
            ),
        )
        txt_box.tag_bind(
            h_tag, "<Enter>", lambda _e: txt_box.config(cursor="hand2")
        )
        txt_box.tag_bind(
            h_tag, "<Leave>", lambda _e: txt_box.config(cursor="")
        )
        txt_box.tag_bind(
            d_tag,
            "<Button-1>",
            lambda _e, i=idx_val: _set_details_collapsed(
                i, not versions[i]["details_collapsed"]
            ),
        )
        txt_box.tag_bind(
            d_tag, "<Enter>", lambda _e: txt_box.config(cursor="hand2")
        )
        txt_box.tag_bind(
            d_tag, "<Leave>", lambda _e: txt_box.config(cursor="")
        )

    def _jump_to_index(v_idx):
        if not versions:
            return 0
        v_idx = max(0, min(len(versions) - 1, int(v_idx)))
        if versions[v_idx]["collapsed"]:
            _set_version_collapsed(v_idx, False)
        ranges = txt_box.tag_ranges(versions[v_idx]["hdr_tag"])
        if ranges:
            txt_box.see(ranges[0])
            txt_box.yview(ranges[0])
        else:
            txt_box.yview(versions[v_idx]["mark"])
        return v_idx

    def _set_all_versions_collapsed(collapsed_bool):
        for i in range(len(versions)):
            _set_version_collapsed(i, collapsed_bool)

    def _set_all_details_collapsed(collapsed_bool):
        for i in range(len(versions)):
            if collapsed_bool and versions[i]["collapsed"]:
                _set_version_collapsed(i, False)
            _set_details_collapsed(i, collapsed_bool)

    return {
        "versions": versions,
        "jump_to_index": _jump_to_index,
        "set_version_collapsed": _set_version_collapsed,
        "set_details_collapsed": _set_details_collapsed,
        "set_all_versions_collapsed": _set_all_versions_collapsed,
        "set_all_details_collapsed": _set_all_details_collapsed,
    }


def _build_changelog_nav_bar(parent_card, txt_box, nav_ctrl):
    """Builds a compact interactive version-jumping and collapse/expand toolbar
    above the Release Notes text box."""
    versions = nav_ctrl.get("versions", []) if isinstance(nav_ctrl, dict) else []
    if not versions:
        return None

    nav_state = {
        "cur_idx": 0,
        "summaries_only": False,
        "all_collapsed": False,
        "popup": None,
    }

    nav_bar = tk.Frame(
        parent_card,
        bg="#0f151e",
        bd=0,
        highlightthickness=1,
        highlightbackground="#222d3d",
        padx=8,
        pady=5,
    )
    nav_bar.pack(fill="x", pady=(0, 6))

    tk.Label(
        nav_bar,
        text="Release:",
        font=("Arial", 8, "bold"),
        fg="#94a3b8",
        bg="#0f151e",
    ).pack(side="left", padx=(2, 4))

    def _close_ver_popup(*_):
        top_win = parent_card.winfo_toplevel()
        for seq, bid in nav_state.get("top_bind_ids", []):
            try:
                top_win.unbind(seq, bid)
            except Exception:
                pass
        nav_state["top_bind_ids"] = []
        pop = nav_state.get("popup")
        nav_state["popup"] = None
        if pop is not None:
            try:
                pop.destroy()
            except Exception:
                pass

    def _select_version(idx):
        _close_ver_popup()
        actual_idx = nav_ctrl["jump_to_index"](idx)
        nav_state["cur_idx"] = actual_idx
        ver_pick_btn.config(text=f"{versions[actual_idx]['label']}  ▾")

    def _open_version_picker():
        if nav_state.get("popup") is not None:
            _close_ver_popup()
            return
        try:
            top_win = parent_card.winfo_toplevel()
            pop = tk.Toplevel(top_win)
            pop.withdraw()
            pop.wm_overrideredirect(True)
            pop.attributes("-topmost", True)
            pop.config(bg="#38bdf8", padx=1, pady=1)
            nav_state["popup"] = pop
            nav_state["top_bind_ids"] = []

            list_frame = tk.Frame(pop, bg="#111722")
            list_frame.pack(fill="both", expand=True)

            vis_rows = min(12, len(versions))
            lb_sb = tk.Scrollbar(list_frame)
            lb_sb.pack(side="right", fill="y")
            lb = tk.Listbox(
                list_frame,
                height=vis_rows,
                width=26,
                bg="#111722",
                fg="#e2e8f0",
                selectbackground="#1e3a5f",
                selectforeground="#38bdf8",
                font=("Segoe UI", 9, "bold"),
                bd=0,
                highlightthickness=0,
                activestyle="none",
                yscrollcommand=lb_sb.set,
                cursor="hand2",
            )
            lb.pack(side="left", fill="both", expand=True, padx=2, pady=2)
            lb_sb.config(command=lb.yview)

            for v_item in versions:
                lb.insert("end", f"  {v_item['label']}")
            lb.selection_set(nav_state["cur_idx"])
            lb.see(nav_state["cur_idx"])

            def _on_lb_click(_evt=None):
                sel = lb.curselection()
                if sel:
                    _select_version(int(sel[0]))

            def _on_lb_motion(evt):
                try:
                    hov_idx = lb.nearest(evt.y)
                    if 0 <= hov_idx < len(versions):
                        lb.selection_clear(0, "end")
                        lb.selection_set(hov_idx)
                except Exception:
                    pass

            def _on_lb_wheel(evt):
                try:
                    delta = int(-1 * (evt.delta / 120))
                    if delta != 0:
                        lb.yview_scroll(delta, "units")
                except Exception:
                    pass
                return "break"

            lb.bind("<Motion>", _on_lb_motion)
            lb.bind("<MouseWheel>", _on_lb_wheel)
            lb.bind("<ButtonRelease-1>", _on_lb_click)
            lb.bind("<Return>", _on_lb_click)

            pop.update_idletasks()
            pop_w = max(
                int(pop.winfo_reqwidth()), int(ver_pick_btn.winfo_width()), 200
            )
            pop_h = max(int(pop.winfo_reqheight()), 80)
            bx = int(ver_pick_btn.winfo_rootx())
            by = int(
                ver_pick_btn.winfo_rooty() + ver_pick_btn.winfo_height() + 2
            )
            m_left, m_top, m_right, m_bottom = get_monitor_work_area(
                bx, by, widget=ver_pick_btn
            )
            if by + pop_h > m_bottom - 8:
                by = max(m_top + 8, int(ver_pick_btn.winfo_rooty()) - pop_h - 2)
            if bx + pop_w > m_right - 8:
                bx = max(m_left + 8, m_right - pop_w - 8)
            bx = max(m_left + 8, bx)
            by = max(m_top + 8, by)
            pop.wm_geometry(f"{pop_w}x{pop_h}+{int(bx)}+{int(by)}")
            pop.deiconify()
            pop.lift()
            try:
                lb.focus_force()
            except Exception:
                pass

            pop.bind("<Escape>", _close_ver_popup)
            lb.bind("<Escape>", _close_ver_popup)

            def _on_top_click(evt):
                try:
                    w_obj = getattr(evt, "widget", None)
                    w_str = str(w_obj or "")
                    if w_str.startswith(str(pop)) or w_obj is ver_pick_btn:
                        return
                except Exception:
                    pass
                _close_ver_popup()

            def _bind_outside_dismiss():
                if nav_state.get("popup") is not pop or not pop.winfo_exists():
                    return
                try:
                    b1 = top_win.bind("<Button-1>", _on_top_click, add="+")
                    if b1:
                        nav_state["top_bind_ids"].append(("<Button-1>", b1))
                    for seq in ("<Configure>", "<Unmap>", "<Escape>"):
                        bid = top_win.bind(seq, _close_ver_popup, add="+")
                        if bid:
                            nav_state["top_bind_ids"].append((seq, bid))
                except Exception:
                    pass

            pop.after(30, _bind_outside_dismiss)
        except Exception:
            _close_ver_popup()

    ver_pick_btn = make_stadium_button(
        nav_bar,
        text=f"{versions[0]['label']}  ▾",
        font=("Arial", 8, "bold"),
        fill_color="#141e2c",
        fill_top_color="#1c2a3d",
        border_color="#2e4766",
        hover_fill="#1b2b3f",
        hover_fill_top="#243852",
        hover_border="#38bdf8",
        fg="#7dd3fc",
        hover_fg="#ffffff",
        canvas_bg="#0f151e",
        width=174,
        height=24,
        auto_width=True,
        pad_x=14,
        command=_open_version_picker,
    )
    ver_pick_btn.pack(side="left", padx=(0, 4))

    def _detect_visible_version_index():
        """Finds whichever version header is currently at or just above the top
        of the viewport so Prev/Next works naturally even after manual scrolling."""
        try:
            top_idx = txt_box.index("@0,8")
            best_i = 0
            for v_item in versions:
                ranges = txt_box.tag_ranges(v_item["hdr_tag"])
                if ranges and txt_box.compare(ranges[0], "<=", top_idx):
                    best_i = v_item["idx"]
            return best_i
        except Exception:
            return nav_state["cur_idx"]

    def _step_version(delta):
        base_i = _detect_visible_version_index()
        if base_i != nav_state["cur_idx"] and delta > 0:
            target_i = max(0, min(len(versions) - 1, base_i + delta))
        else:
            target_i = max(0, min(len(versions) - 1, nav_state["cur_idx"] + delta))
        _select_version(target_i)

    make_stadium_button(
        nav_bar,
        text="▲ Newer",
        font=("Arial", 8, "bold"),
        fill_color="#141820",
        border_color="#334155",
        hover_fill="#1e2633",
        hover_border="#64748b",
        fg="#cbd5e1",
        hover_fg="#ffffff",
        canvas_bg="#0f151e",
        width=68,
        height=24,
        auto_width=True,
        pad_x=12,
        command=lambda: _step_version(-1),
    ).pack(side="left", padx=(0, 3))

    make_stadium_button(
        nav_bar,
        text="▼ Older",
        font=("Arial", 8, "bold"),
        fill_color="#141820",
        border_color="#334155",
        hover_fill="#1e2633",
        hover_border="#64748b",
        fg="#cbd5e1",
        hover_fg="#ffffff",
        canvas_bg="#0f151e",
        width=68,
        height=24,
        auto_width=True,
        pad_x=12,
        command=lambda: _step_version(1),
    ).pack(side="left", padx=(0, 6))

    def _toggle_collapse_all():
        _close_ver_popup()
        nav_state["all_collapsed"] = not nav_state["all_collapsed"]
        nav_ctrl["set_all_versions_collapsed"](nav_state["all_collapsed"])
        if nav_state["all_collapsed"]:
            collapse_all_btn.config(
                text="▼ Expand All Releases",
                fg="#6ee7b7",
                border_color="#059669",
            )
            txt_box.see("1.0")
        else:
            collapse_all_btn.config(
                text="▶ Collapse All Releases",
                fg="#cbd5e1",
                border_color="#334155",
            )

    collapse_all_btn = make_stadium_button(
        nav_bar,
        text="▶ Collapse All Releases",
        font=("Arial", 8, "bold"),
        fill_color="#141820",
        border_color="#334155",
        hover_fill="#1e2633",
        hover_border="#64748b",
        fg="#cbd5e1",
        hover_fg="#ffffff",
        canvas_bg="#0f151e",
        width=136,
        height=24,
        auto_width=True,
        pad_x=12,
        command=_toggle_collapse_all,
    )
    collapse_all_btn.pack(side="right", padx=(3, 0))

    def _toggle_summaries_only():
        _close_ver_popup()
        nav_state["summaries_only"] = not nav_state["summaries_only"]
        if nav_state["summaries_only"] and nav_state["all_collapsed"]:
            nav_state["all_collapsed"] = False
            collapse_all_btn.config(
                text="▶ Collapse All Releases",
                fg="#cbd5e1",
                border_color="#334155",
            )
        nav_ctrl["set_all_details_collapsed"](nav_state["summaries_only"])
        if nav_state["summaries_only"]:
            sum_only_btn.config(
                text="⚡ Summaries Only: ON",
                fill_color="#2a2110",
                border_color="#f59e0b",
                fg="#fde68a",
            )
        else:
            sum_only_btn.config(
                text="⚡ Summaries Only",
                fill_color="#141820",
                border_color="#334155",
                fg="#fbbf24",
            )

    sum_only_btn = make_stadium_button(
        nav_bar,
        text="⚡ Summaries Only",
        font=("Arial", 8, "bold"),
        fill_color="#141820",
        border_color="#334155",
        hover_fill="#262014",
        hover_border="#fbbf24",
        fg="#fbbf24",
        hover_fg="#fde68a",
        canvas_bg="#0f151e",
        width=118,
        height=24,
        auto_width=True,
        pad_x=12,
        command=_toggle_summaries_only,
    )
    sum_only_btn.pack(side="right", padx=(0, 3))

    return nav_bar


def show_update_available_dialog(
    curr_ver, new_ver, changelog_md="", parent=None
):
    """Displays a dark-themed GUI popup when a new version is available,
    showing release notes and a clickable link to the full Changelog."""
    decision = {"install": False}
    try:
        is_standalone = parent is None
        if not is_standalone:
            hide_all_tooltips()
        win = tk.Tk() if is_standalone else tk.Toplevel(parent)
        win.withdraw()
        if not is_standalone:
            win.transient(parent)
        if os.path.exists(ICON_PATH):
            try:
                win.iconbitmap(ICON_PATH)
            except Exception:
                pass
        apply_dark_title_bar(win)
        win.title(f"PnL Enforcer Beta — Update Available (v{new_ver})")
        win.config(bg="#0d1117", padx=24, pady=18)
        win.resizable(True, True)
        win.minsize(780, 500)
        win.attributes("-topmost", True)

        m_left, m_top, m_right, m_bottom = get_monitor_work_area(
            widget=(parent if parent is not None else win)
        )
        mw = max(800, m_right - m_left)
        mh = max(600, m_bottom - m_top)
        w = min(1040, max(780, mw - 80))
        h = min(690, max(500, mh - 80))

        hdr_row = tk.Frame(win, bg="#0d1117")
        hdr_row.pack(fill="x")

        tk.Label(
            hdr_row,
            text=f"🚀 UPDATE AVAILABLE:  v{curr_ver}  ➔  v{new_ver}",
            font=("Arial", 13, "bold"),
            fg="#00e676",
            bg="#0d1117",
            anchor="w",
        ).pack(side="left")

        make_stadium_button(
            hdr_row,
            text="Open Full Changelog ↗",
            font=("Arial", 9, "bold"),
            fill_color="#132235",
            border_color="#2b6cb0",
            hover_fill="#1c3452",
            hover_border="#63b3ed",
            fg="#e0f2fe",
            hover_fg="#ffffff",
            canvas_bg="#0d1117",
            height=30,
            pad_x=20,
            command=lambda: webbrowser.open(get_changelog_web_url()),
        ).pack(side="right")

        make_stadium_button(
            hdr_row,
            text="Inspect Source ↗",
            font=("Arial", 9, "bold"),
            fill_color="#161f2c",
            border_color="#475569",
            hover_fill="#1f2c3f",
            hover_border="#94a3b8",
            fg="#cbd5e1",
            hover_fg="#ffffff",
            canvas_bg="#0d1117",
            height=30,
            pad_x=20,
            command=lambda: webbrowser.open(get_source_diff_web_url()),
        ).pack(side="right", padx=(0, 8))

        tk.Label(
            win,
            text=(
                "Your saved Pre-Flight settings, daily account baselines, and "
                "broker API tokens are 100% preserved."
            ),
            font=("Arial", 9, "bold"),
            fg="#94a3b8",
            bg="#0d1117",
            anchor="w",
        ).pack(fill="x", pady=(4, 10))

        # Pack bottom button bar BEFORE the expandable changelog card so
        # Tkinter always reserves space for the buttons at the bottom.
        btn_bar = tk.Frame(win, bg="#0d1117", pady=12)
        btn_bar.pack(fill="x", side="bottom")

        def on_skip():
            decision["install"] = False
            win.destroy()

        def on_install():
            decision["install"] = True
            win.destroy()

        make_stadium_button(
            btn_bar,
            text=f"Skip for Now (Keep v{curr_ver})",
            font=("Arial", 10, "bold"),
            fill_color="#181e26",
            border_color="#4a5568",
            hover_fill="#232c38",
            hover_border="#718096",
            fg="#d1d5db",
            hover_fg="#ffffff",
            canvas_bg="#0d1117",
            height=34,
            pad_x=26,
            command=on_skip,
        ).pack(side="left")

        make_stadium_button(
            btn_bar,
            text=f"🚀 Install v{new_ver} & Launch >>",
            font=("Arial", 10, "bold"),
            fill_color="#0f6b3c",
            border_color="#00e676",
            hover_fill="#15854b",
            hover_border="#69f0ae",
            glow_color="#00e676",
            glow_strength=0.68,
            fg="#ffffff",
            hover_fg="#ffffff",
            canvas_bg="#0d1117",
            height=36,
            pad_x=30,
            command=on_install,
        ).pack(side="right")

        card_outer = tk.Frame(
            win,
            bg="#131922",
            bd=0,
            highlightthickness=1,
            highlightbackground="#243040",
        )
        card_outer.pack(fill="both", expand=True)
        accent_bar = NeonBarCanvas(
            card_outer, core_color="#00e676", card_bg="#131922", glow_on=True
        )
        accent_bar.pack(side="left", fill="y")
        card = tk.Frame(card_outer, bg="#131922", padx=12, pady=10)
        card.pack(side="left", fill="both", expand=True)

        tk.Label(
            card,
            text=f"▶ WHAT'S NEW IN v{new_ver} (CHANGELOG):",
            font=("Arial", 9, "bold"),
            fg="#38bdf8",
            bg="#131922",
            anchor="w",
        ).pack(fill="x", pady=(0, 6))

        nav_holder = tk.Frame(card, bg="#131922")
        nav_holder.pack(fill="x")

        txt_frame = tk.Frame(
            card,
            bg="#151d28",
            bd=0,
            highlightthickness=1,
            highlightbackground="#263548",
        )
        txt_frame.pack(fill="both", expand=True)

        sb = tk.Scrollbar(txt_frame)
        sb.pack(side="right", fill="y")

        txt_box = tk.Text(
            txt_frame,
            height=12,
            bg="#151d28",
            fg="#dce4ee",
            font=("Arial", 10, "bold"),
            wrap="word",
            bd=0,
            padx=10,
            pady=8,
            yscrollcommand=sb.set,
        )
        txt_box.pack(side="left", fill="both", expand=True)
        sb.config(command=txt_box.yview)

        display_notes = (changelog_md or "").strip()
        if not display_notes:
            display_notes = (
                f"PnL Enforcer Beta v{new_ver} is ready to install.\n\n"
                f"Click 'Open Full Changelog ↗' above to view full release notes."
            )
        nav_ctrl = _insert_formatted_changelog(txt_box, display_notes)
        if len(nav_ctrl.get("versions", [])) > 1:
            _build_changelog_nav_bar(nav_holder, txt_box, nav_ctrl)
        txt_box.see("1.0")
        txt_box.config(state="disabled")

        win.protocol("WM_DELETE_WINDOW", on_skip)
        center_dialog_over_parent(win, parent=parent, width=w, height=h)
        if not is_standalone:
            try:
                win.grab_set()
            except Exception:
                pass
        win.lift()
        win.focus_force()
        if is_standalone:
            win.mainloop()
        else:
            parent.wait_window(win)
        return decision["install"]
    except Exception:
        if (
            parent is None
            and sys.stdin is not None
            and getattr(sys.stdin, "isatty", lambda: False)()
        ):
            try:
                ans = input(
                    f"Download and install v{new_ver} now? (Y/N): "
                ).strip().lower()
                return ans in ("y", "yes")
            except Exception:
                return False
        return False


def _check_version_switch_guardrails(
    from_live_hud=False, action_label="Rollback", log_block=True
):
    """Shared anti-tamper gate for in-app version switching (Rollback or Manual
    Update install): blocks switching while the live HUD is open, while any
    today-dated session lock / cooldown / rolling tilt streak is active on any
    real broker account, or while any tracked real-broker position is open."""
    def _deny(code_s, log_s, user_s):
        if log_block and log_s:
            log_event("GUARDRAIL", log_s)
        return False, code_s, user_s

    if from_live_hud:
        return _deny(
            "HUD_OPEN",
            "",
            f"Close the live HUD first before running {action_label.lower()}.\n\n"
            "Exit the HUD to standalone Pre-Flight (when flat and unlocked), then try again.",
        )

    now_ep = time.time()
    today_str = get_today_str()
    mem_cfg = config if isinstance(config, dict) else {}
    ad_cur = globals().get("active_adapter")
    in_demo_now = bool(
        callable(globals().get("is_demo_mode_active"))
        and globals()["is_demo_mode_active"](ad_cur)
    )

    if (
        globals().get("dry_run_lock_active", False)
        or (globals().get("cooldown_active", False) and not in_demo_now)
        or float(mem_cfg.get("active_cooldown_end_epoch", 0.0) or 0.0) > now_ep
    ):
        return _deny(
            "GUARDRAIL",
            f"BLOCKED: Attempted {action_label.lower()} during an active Penalty Box / Lockout timer.",
            f"{action_label} is blocked while a Penalty Box / OS Lockout cooldown timer is active.",
        )

    if mem_cfg.get("committed_session_date") == today_str or (
        callable(globals().get("is_real_broker_committed_for_today"))
        and globals()["is_real_broker_committed_for_today"]()
    ):
        return _deny(
            "GUARDRAIL",
            f"BLOCKED: Attempted {action_label.lower()} while 'Commit Rulebook for Today' is active.",
            f"{action_label} is locked until 00:00 Midnight ET because 'Commit Rulebook for Today' is active.",
        )

    if not in_demo_now and globals().get("done_for_today", False):
        return _deny(
            "GUARDRAIL",
            f"BLOCKED: Attempted {action_label.lower()} while 'Done for Today' is active.",
            f"{action_label} is locked while 'Done for Today' is active.\n\n"
            "Unlock 'Done Today' in Card 3 first if you need to switch versions.",
        )

    if not in_demo_now and globals().get("is_locked_down", False):
        return _deny(
            "GUARDRAIL",
            f"BLOCKED: Attempted {action_label.lower()} while Daily Stop Breach Lockout is active.",
            f"{action_label} is blocked while Daily Stop Breach Lockout is active today.",
        )

    tilt_en = bool(mem_cfg.get("enable_consec_loss_cooldown", False))
    tilt_win_s = max(
        0.5, float(mem_cfg.get("consec_loss_window_mins", 15.0) or 15.0)
    ) * 60.0

    for sess_k, sess_v in (mem_cfg.get("account_sessions") or {}).items():
        if not isinstance(sess_v, dict) or str(sess_k).upper().startswith("DEMO"):
            continue
        if sess_v.get("committed_for_today") and (
            sess_v.get("committed_date") == today_str
            or sess_v.get("session_date") == today_str
        ):
            return _deny(
                "GUARDRAIL",
                f"BLOCKED: Attempted {action_label.lower()} while 'Commit Today' is active on {sess_k}.",
                f"{action_label} is locked until 00:00 Midnight ET because 'Commit Rulebook for Today' is active.",
            )
        if (
            sess_v.get("done_for_today")
            and sess_v.get("done_for_today_date") == today_str
        ):
            return _deny(
                "GUARDRAIL",
                f"BLOCKED: Attempted {action_label.lower()} while 'Done for Today' is active on {sess_k}.",
                f"{action_label} is locked while 'Done for Today' is active on your live account.",
            )
        if sess_v.get("is_locked_down") and sess_v.get("breach_date") == today_str:
            return _deny(
                "GUARDRAIL",
                f"BLOCKED: Attempted {action_label.lower()} while Daily Stop Breach Lockout is active on {sess_k}.",
                f"{action_label} is blocked while Daily Stop Breach Lockout is active today.",
            )
        if tilt_en and (
            not sess_v.get("session_date")
            or sess_v.get("session_date") == today_str
        ):
            for loss_ts in sess_v.get("recent_loss_timestamps") or []:
                try:
                    if (now_ep - float(loss_ts)) < tilt_win_s:
                        return _deny(
                            "GUARDRAIL",
                            f"BLOCKED: Attempted {action_label.lower()} during active Consecutive Loss Streak on {sess_k}.",
                            f"{action_label} is locked while an active Consecutive Loss Streak is on the rolling clock.",
                        )
                except Exception:
                    return _deny(
                        "GUARDRAIL",
                        f"BLOCKED: Attempted {action_label.lower()} with unverified tilt streak state on {sess_k}.",
                        f"{action_label} is locked because tilt streak state could not be verified.",
                    )

    if not in_demo_now and tilt_en:
        try:
            cur_s, _req_l, _nx_s, _fl_s, _en_b = get_loss_streak_status()
            if cur_s > 0:
                return _deny(
                    "GUARDRAIL",
                    f"BLOCKED: Attempted {action_label.lower()} during active Consecutive Loss Streak.",
                    f"{action_label} is locked while an active Consecutive Loss Streak is on the rolling clock.",
                )
        except Exception:
            return _deny(
                "GUARDRAIL",
                f"BLOCKED: Attempted {action_label.lower()} while tilt streak verification raised an error.",
                f"{action_label} is locked because tilt streak state could not be verified.",
            )

    if ad_cur is not None and not in_demo_now:
        ig_set = globals().get("ignored_positions") or set()
        has_open_tracked = not bool(globals().get("current_is_flat", True))
        if not has_open_tracked and hasattr(ad_cur, "get_last_raw_pos_details"):
            try:
                raw_p = ad_cur.get_last_raw_pos_details() or {}
                for p_tag, p_info in raw_p.items():
                    if p_tag in ig_set or not isinstance(p_info, dict):
                        continue
                    if abs(float(p_info.get("qty", 0) or 0)) > 1e-9:
                        has_open_tracked = True
                        break
            except Exception:
                return _deny(
                    "GUARDRAIL",
                    f"BLOCKED: Attempted {action_label.lower()} while open-position check failed.",
                    f"{action_label} is blocked because live position status could not be verified.",
                )
        if has_open_tracked:
            return _deny(
                "GUARDRAIL",
                f"BLOCKED: Attempted {action_label.lower()} while a tracked live position is open.",
                f"{action_label} is blocked while a tracked position is open.\n\n"
                "Flatten your active daytrade (or mark pre-existing swing positions Ignored) first.",
            )

    return True, "OK", ""


def check_rollback_allowed(from_live_hud=False):
    """Verifies whether in-app version rollback is permitted right now.
    Returns (allowed_bool, status_code, rb_info_dict, message_str)."""
    rb_info = get_rollback_backup_info()
    if not rb_info.get("available"):
        reason_code = rb_info.get("reason") or "NO_BACKUP"
        return False, reason_code, rb_info, "No previous version backup is saved yet."
    ok_sw, sw_code, sw_msg = _check_version_switch_guardrails(
        from_live_hud=from_live_hud, action_label="Rollback"
    )
    if not ok_sw:
        return False, sw_code, rb_info, sw_msg
    return True, "OK", rb_info, ""


def execute_version_rollback(
    cancel_pf_fn=None, close_wins=(), spawn_relaunch=True
):
    """Restores enforcer.py.prev -> enforcer.py, records skipped_update_version
    so the reverted release does not immediately re-prompt on startup, preserves
    100% of config/baselines, and relaunches into the restored version."""
    allowed, _code, _info, err_msg = check_rollback_allowed(from_live_hud=False)
    if not allowed:
        return False, err_msg
    ok_disk, prev_ver = _restore_prev_files_to_disk()
    if not ok_disk:
        return False, "Could not restore enforcer.py.prev (file missing or invalid)."
    _record_skipped_update_version_on_disk(APP_VERSION)
    log_event(
        "SESSION",
        f"Rolled back PnL Enforcer from v{APP_VERSION} to v{prev_ver} "
        f"(skipped_update_version={APP_VERSION}).",
    )
    if callable(cancel_pf_fn):
        try:
            cancel_pf_fn()
        except Exception:
            pass
    for w_obj in close_wins or ():
        if w_obj is not None:
            try:
                if w_obj.winfo_exists():
                    w_obj.destroy()
            except Exception:
                pass
    if spawn_relaunch:
        _release_single_instance_mutex()
        _spawn_updated_enforcer(os.path.join(SCRIPT_DIR, "enforcer.py"))
    return True, prev_ver


def prompt_version_rollback_dialog(
    parent_win=None,
    from_live_hud=False,
    cancel_pf_fn=None,
    extra_close_win=None,
):
    """Opens a dark-glass confirmation modal to restore enforcer.py.prev in one
    click (or shows an informational 'Rollback Armed' status card if no .prev
    backup exists yet, or a guardrail notice if rollback is currently locked)."""
    hide_all_tooltips()
    allowed, code, rb_info, block_msg = check_rollback_allowed(
        from_live_hud=from_live_hud
    )

    if code in ("NO_BACKUP", "SAME_VERSION", "CORRUPT_BACKUP"):
        dlg = (
            tk.Tk()
            if parent_win is None
            else tk.Toplevel(parent_win)
        )
        dlg.withdraw()
        if parent_win is not None:
            dlg.transient(parent_win)
        if os.path.exists(ICON_PATH):
            try:
                dlg.iconbitmap(ICON_PATH)
            except Exception:
                pass
        dlg.title("PnL Enforcer — Automatic Update Rollback")
        dlg.config(bg="#0d1117", padx=24, pady=18)
        dlg.resizable(False, False)
        dlg.attributes("-topmost", True)

        tk.Label(
            dlg,
            text=f"▶ ↺ AUTOMATIC UPDATE ROLLBACK  (ARMED ON v{APP_VERSION})",
            font=("Arial", 11, "bold"),
            fg="#7dd3fc",
            bg="#0d1117",
            anchor="w",
        ).pack(fill="x", pady=(0, 10))

        card_o = tk.Frame(
            dlg,
            bg="#131922",
            bd=0,
            highlightthickness=1,
            highlightbackground="#243040",
        )
        card_o.pack(fill="x", pady=(0, 14))
        NeonBarCanvas(
            card_o, core_color="#38bdf8", card_bg="#131922", glow_on=True
        ).pack(side="left", fill="y")
        body_f = tk.Frame(card_o, bg="#131922", padx=16, pady=12)
        body_f.pack(side="left", fill="both", expand=True)

        skipped_v = _peek_saved_skipped_update_version()
        if code == "SAME_VERSION":
            info_txt = (
                f"You are already running your restored backup version (v{APP_VERSION}).\n\n"
                + (
                    f"• Automatic startup prompts for v{skipped_v} are paused until a newer update ships.\n"
                    if skipped_v
                    else ""
                )
                + "• Use '📜 Logs ▾ -> 🔄 Check for Updates Now...' anytime to manually check or re-install updates."
            )
        elif code == "CORRUPT_BACKUP":
            info_txt = (
                "An older enforcer.py.prev file was found, but it did not pass integrity verification.\n\n"
                f"• PnL Enforcer will automatically write a fresh verified backup of v{APP_VERSION} before your next update."
            )
        else:
            info_txt = (
                f"No previous backup file exists yet because v{APP_VERSION} is your active baseline install.\n\n"
                "• Automatic Local Backup: Right before installing any future update, PnL Enforcer automatically "
                "saves a verified copy of your current working script (enforcer.py.prev).\n"
                "• One-Click Restore: Anytime after your next update, click here (or in View Release Notes / "
                "the bottom-right Rollback link) to revert in one click while keeping 100% of your saved settings, "
                "broker API tokens, and today's baseline.\n"
                "• Crash-Safe Boot Recovery: If a future update ever fails to launch, PnL Enforcer and "
                "Launch_Enforcer.bat will automatically offer to restore your previous working version."
            )

        tk.Label(
            body_f,
            text=info_txt,
            font=("Arial", 9, "bold"),
            fg="#cbd5e1",
            bg="#131922",
            justify="left",
            wraplength=580,
            anchor="w",
        ).pack(fill="x")

        b_row = tk.Frame(dlg, bg="#0d1117")
        b_row.pack(fill="x")
        make_stadium_button(
            b_row,
            text="Got It ✓",
            font=("Arial", 10, "bold"),
            fill_color="#13283d",
            fill_top_color="#1a3652",
            border_color="#38bdf8",
            hover_fill="#163049",
            hover_fill_top="#1e3e5d",
            hover_border="#7dd3fc",
            fg="#e0f2fe",
            canvas_bg="#0d1117",
            height=34,
            pad_x=28,
            command=dlg.destroy,
        ).pack(side="right")

        prev_grab_win = None
        if parent_win is not None:
            try:
                prev_grab_win = parent_win.grab_current()
            except Exception:
                prev_grab_win = None

        dlg.update_idletasks()
        center_dialog_over_parent(dlg, parent=parent_win)
        if parent_win is not None:
            try:
                dlg.grab_set()
            except Exception:
                pass
            dlg.focus_set()
            parent_win.wait_window(dlg)
            if prev_grab_win is not None:
                try:
                    if prev_grab_win.winfo_exists():
                        prev_grab_win.grab_set()
                except Exception:
                    pass
            if parent_win.winfo_exists():
                try:
                    parent_win.lift()
                    parent_win.focus_force()
                except Exception:
                    pass
        else:
            dlg.mainloop()
        return False

    if not allowed:
        messagebox.showwarning(
            "Version Rollback Locked",
            block_msg,
            parent=parent_win,
        )
        return False

    prev_ver = rb_info["prev_version"]
    mtime_str = rb_info.get("mtime_str") or "local backup"
    confirmed = {"ok": False}

    dlg = tk.Tk() if parent_win is None else tk.Toplevel(parent_win)
    dlg.withdraw()
    if parent_win is not None:
        dlg.transient(parent_win)
    if os.path.exists(ICON_PATH):
        try:
            dlg.iconbitmap(ICON_PATH)
        except Exception:
            pass
    dlg.title(f"Restore Previous Version (v{prev_ver})")
    dlg.config(bg="#0d1117", padx=24, pady=18)
    dlg.resizable(False, False)
    dlg.attributes("-topmost", True)

    tk.Label(
        dlg,
        text=f"▶ ↺ RESTORE PREVIOUS VERSION:  v{APP_VERSION}  ➔  v{prev_ver}",
        font=("Arial", 11, "bold"),
        fg="#7dd3fc",
        bg="#0d1117",
        anchor="w",
    ).pack(fill="x", pady=(0, 10))

    card_o = tk.Frame(
        dlg,
        bg="#131922",
        bd=0,
        highlightthickness=1,
        highlightbackground="#243040",
    )
    card_o.pack(fill="x", pady=(0, 14))
    NeonBarCanvas(
        card_o, core_color="#f59e0b", card_bg="#131922", glow_on=True
    ).pack(side="left", fill="y")
    body_f = tk.Frame(card_o, bg="#131922", padx=16, pady=12)
    body_f.pack(side="left", fill="both", expand=True)

    summary_txt = (
        f"• Restores your verified local backup (v{prev_ver}, saved {mtime_str}) and relaunches immediately.\n\n"
        "• 100% of your saved Pre-Flight settings, broker API tokens, and today's session baseline remain untouched.\n\n"
        f"• Pauses automatic startup prompts for v{APP_VERSION} so you won't be nagged on relaunch "
        "(resumes automatically when a newer release ships, or anytime via Logs ▾ -> Check for Updates Now)."
    )
    tk.Label(
        body_f,
        text=summary_txt,
        font=("Arial", 9, "bold"),
        fg="#cbd5e1",
        bg="#131922",
        justify="left",
        wraplength=580,
        anchor="w",
    ).pack(fill="x")

    if globals().get("active_adapter") is None:
        tk.Label(
            body_f,
            text="⚠️ No live broker is currently connected — verify any open positions directly in your broker platform.",
            font=("Arial", 9, "bold"),
            fg="#fbbf24",
            bg="#131922",
            justify="left",
            wraplength=580,
            anchor="w",
        ).pack(fill="x", pady=(10, 0))

    def _on_cancel():
        confirmed["ok"] = False
        dlg.destroy()

    def _on_confirm():
        confirmed["ok"] = True
        dlg.destroy()

    b_row = tk.Frame(dlg, bg="#0d1117")
    b_row.pack(fill="x")
    make_stadium_button(
        b_row,
        text=f"Cancel (Stay on v{APP_VERSION})",
        font=("Arial", 10, "bold"),
        fill_color="#181e26",
        border_color="#4a5568",
        hover_fill="#232c38",
        hover_border="#718096",
        fg="#cbd5e1",
        hover_fg="#ffffff",
        canvas_bg="#0d1117",
        height=34,
        pad_x=24,
        command=_on_cancel,
    ).pack(side="left")

    make_stadium_button(
        b_row,
        text=f"↺ Restore v{prev_ver} & Relaunch >>",
        font=("Arial", 10, "bold"),
        fill_color="#33220c",
        fill_top_color="#473010",
        border_color="#f59e0b",
        hover_fill="#3f2a0f",
        hover_fill_top="#543813",
        hover_border="#fbbf24",
        fg="#fde68a",
        hover_fg="#ffffff",
        canvas_bg="#0d1117",
        height=34,
        pad_x=28,
        command=_on_confirm,
    ).pack(side="right")

    prev_grab_win = None
    if parent_win is not None:
        try:
            prev_grab_win = parent_win.grab_current()
        except Exception:
            prev_grab_win = None

    dlg.protocol("WM_DELETE_WINDOW", _on_cancel)
    dlg.update_idletasks()
    center_dialog_over_parent(dlg, parent=parent_win)
    if parent_win is not None:
        try:
            dlg.grab_set()
        except Exception:
            pass
        dlg.focus_set()
        parent_win.wait_window(dlg)
    else:
        dlg.mainloop()

    if not confirmed["ok"]:
        if prev_grab_win is not None:
            try:
                if prev_grab_win.winfo_exists():
                    prev_grab_win.grab_set()
            except Exception:
                pass
        if parent_win is not None and parent_win.winfo_exists():
            try:
                parent_win.lift()
                parent_win.focus_force()
            except Exception:
                pass
        return False

    ok_exec, res_msg = execute_version_rollback(
        cancel_pf_fn=cancel_pf_fn,
        close_wins=[w for w in (parent_win, extra_close_win) if w is not None],
        spawn_relaunch=True,
    )
    if not ok_exec and parent_win is not None and parent_win.winfo_exists():
        messagebox.showerror("Rollback Failed", res_msg, parent=parent_win)
    return ok_exec


def show_release_notes_dialog(
    parent=None, from_live_hud=False, cancel_pf_fn=None
):
    """Opens a dark-themed modal viewer displaying the local or remote
    CHANGELOG.md release notes, with a button to open the full web Changelog."""
    hide_all_tooltips()
    cl_text = ""
    cl_path = os.path.join(SCRIPT_DIR, "CHANGELOG.md")
    if os.path.exists(cl_path):
        try:
            with open(cl_path, "r", encoding="utf-8", errors="replace") as f:
                cl_text = f.read()
        except Exception:
            pass
    if not cl_text.strip():
        cl_bytes = _fetch_remote_doc_bytes("CHANGELOG.md")
        if cl_bytes:
            cl_text = cl_bytes.decode("utf-8", errors="replace")

    if not cl_text.strip():
        webbrowser.open(get_changelog_web_url())
        return

    is_standalone = parent is None
    prev_rn_grab = None
    if not is_standalone:
        try:
            prev_rn_grab = parent.grab_current()
        except Exception:
            prev_rn_grab = None
    win = tk.Tk() if is_standalone else tk.Toplevel(parent)
    win.withdraw()
    if not is_standalone:
        win.transient(parent)
        try:
            win.grab_set()
        except Exception:
            pass

    def _close_rn_win():
        try:
            win.destroy()
        except Exception:
            pass
        if prev_rn_grab is not None:
            try:
                if prev_rn_grab.winfo_exists():
                    prev_rn_grab.grab_set()
            except Exception:
                pass
        if parent is not None:
            try:
                if parent.winfo_exists():
                    parent.lift()
                    parent.focus_force()
            except Exception:
                pass

    win.protocol("WM_DELETE_WINDOW", _close_rn_win)
    if os.path.exists(ICON_PATH):
        try:
            win.iconbitmap(ICON_PATH)
        except Exception:
            pass

    win.title(f"PnL Enforcer Beta — Release Notes (v{APP_VERSION})")
    win.config(bg="#0d1117", padx=24, pady=18)
